static const char s_week[7][4]={"SUN","MON","TUE","WED","THU","FRI","SAT"};
static const uint8_t s_star[4][2]={{6,58},{34,54},{118,6},{122,61}};
static uint32_t s_inM[4][SCENE_DIG_H],s_onM[4][SCENE_DIG_H];
static int8_t s_cache[4]={-1,-1,-1,-1};
static int32_t SegmentDistance(int32_t px,int32_t py,const DigitPoint *a,const DigitPoint *b)
{
    int32_t ax=a->x*16,ay=a->y*16,dx=(b->x-a->x)*16,dy=(b->y-a->y)*16,len=dx*dx+dy*dy,dot=(px-ax)*dx+(py-ay)*dy,qx,qy;
    if(!len) { qx=ax; qy=ay; } else {
        if(dot<0) { dot=0; } if(dot>len) { dot=len; } qx=ax+dx*dot/len; qy=ay+dy*dot/len;
    }
    dx=px-qx; dy=py-qy; return dx*dx+dy*dy;
}
static void Digit_Build(uint8_t slot,uint8_t value)
{
    int32_t x,y,d,best;
    uint8_t k;
    const DigitPath *p=&s_paths[value];
    for(y=0;y<SCENE_DIG_H;y++) {
        s_inM[slot][y]=s_onM[slot][y]=0u;
        for(x=0;x<SCENE_DIG_W;x++) {
            best=0x7FFFFFFFL;
            for(k=0u;k+1u<p->n;k++) { d=SegmentDistance((x-2)*16,(y-2)*16,&p->p[k],&p->p[k+1u]); if(d<best) { best=d; } }
            if(best<=1600) { s_inM[slot][y] |= 1uL<<x; if(best>=576 || best<=64) { s_onM[slot][y] |= 1uL<<x; } }
        }
    }
}
static void Digits_Update(uint8_t h,uint8_t m)
{
    uint8_t w[4],i;
    w[0]=(uint8_t)(h/10u); w[1]=(uint8_t)(h%10u); w[2]=(uint8_t)(m/10u); w[3]=(uint8_t)(m%10u);
    for(i=0u;i<4u;i++) { if(s_cache[i]!=(int8_t)w[i]) { Digit_Build(i,w[i]); s_cache[i]=(int8_t)w[i]; } }
}
static uint8_t TimeArea(int32_t u,int32_t v)
{
    if(u>=SCENE_HOUR_X-2 && u<SCENE_HOUR_X+SCENE_DIG_PITCH+SCENE_DIG_W+2 && v>=SCENE_HOUR_Y-2 && v<SCENE_HOUR_Y+SCENE_DIG_H+2) { return 1u; }
    if(u>=SCENE_MIN_X-2 && u<SCENE_MIN_X+SCENE_DIG_PITCH+SCENE_DIG_W+2 && v>=SCENE_MIN_Y-2 && v<SCENE_MIN_Y+SCENE_DIG_H+2) { return 1u; }
    if(u>=SCENE_SEC_X-2 && u<SCENE_SEC_X+14 && v>=SCENE_SEC_Y-2 && v<SCENE_SEC_Y+9) { return 1u; } return 0u;
}
static int32_t DigitPixel(uint8_t slot,int32_t x,int32_t y)
{
    if(x<0 || y<0 || x>=SCENE_DIG_W || y>=SCENE_DIG_H) { return -1; }
    if(!(s_inM[slot][y] & (1uL<<x))) { return -1; } return (s_onM[slot][y] & (1uL<<x))?1:0;
}
/* Black-hole stroke digit font (s_paths) reused for the moving hour label.
 * The distance field keeps its double white tube strokes; the black gaps stay
 * transparent so no dial pixel is erased. The inverse black-hole transform
 * adds its exact ~12.6 degree lean; ink and 1px guard must be black before paint. */
static uint8_t  s_hv[2]={200u,200u};
static uint32_t s_hOn[2][18];   /* white stroke pixels only; gaps remain transparent */
#define HOUR_MOVE_INTERVAL_MS 100u
static int16_t s_hourX=64,s_hourY=32;
static uint32_t s_hourMoveAt=0u;
static uint8_t s_hourPosValid=0u,s_hourMoveClockValid=0u,s_hourLastDrawn=0u,s_hourLastRadius=0u;
#if defined(FW_SIMULATOR)
static uint32_t s_hourClearTests=0u;
static uint8_t s_hourBase[OLED_H/8][OLED_W];
#endif
static int32_t Stroke_Dist8(int32_t px8,int32_t py8,const DigitPoint *a,const DigitPoint *b)
{
    int32_t ax=a->x*6,ay=a->y*6,dx=(b->x-a->x)*6,dy=(b->y-a->y)*6,len=dx*dx+dy*dy,dot,qx,qy;
    if(!len) { qx=ax; qy=ay; } else {
        dot=(px8-ax)*dx+(py8-ay)*dy;
        if(dot<0) { dot=0; } if(dot>len) { dot=len; }
        qx=ax+dx*dot/len; qy=ay+dy*dot/len;
    }
    dx=px8-qx; dy=py8-qy; return dx*dx+dy*dy;
}
static void Stroke_Build(uint8_t slot,uint8_t value)
{
    int32_t x,y,best,d;
    uint8_t k;
    const DigitPath *p=&s_paths[value];
    for(y=-2;y<16;y++) {
        s_hOn[slot][y+2]=0u;
        for(x=-3;x<12;x++) {
            best=0x7FFFFFFFL;
            for(k=0u;k+1u<p->n;k++) { d=Stroke_Dist8(x*8,y*8,&p->p[k],&p->p[k+1u]); if(d<best) { best=d; } }
            if(best<=225 && (best>=81 || best<=9)) { s_hOn[slot][y+2] |= 1uL<<(x+3); }
        }
    }
}
static int32_t Stroke_RotX(int32_t x,int32_t y)
{
    return (x*SCENE_COS+y*SCENE_SIN)>>8;
}
static int32_t Stroke_RotY(int32_t x,int32_t y)
{
    return (-x*SCENE_SIN+y*SCENE_COS)>>8;
}
static uint8_t Stroke_PositionClear(int32_t cx,int32_t cy)
{
    int32_t slot,y,x,lx,ly,rx,ry,px,py,nx,ny;
    uint32_t mask,bit;
#if defined(FW_SIMULATOR)
    s_hourClearTests++;
#endif
    for(slot=0;slot<2;slot++) {
        for(y=-2;y<16;y++) {
            mask=s_hOn[slot][y+2];
            if(!mask) { continue; }
            for(x=-3;x<12;x++) {
                bit=1uL<<(x+3);
                if(mask&bit) {
                    lx=-12+slot*15+x; ly=-7+y;
                    rx=Stroke_RotX(lx,ly); ry=Stroke_RotY(lx,ly);
                    for(ny=-1;ny<=1;ny++) {
                        py=cy+ry+ny;
                        if((uint32_t)py>=OLED_H) { return 0u; }
                        for(nx=-1;nx<=1;nx++) {
                            px=cx+rx+nx;
                            if((uint32_t)px>=OLED_W) { return 0u; }
                            if(OLED_GRAM[py>>3][px]&(uint8_t)(1u<<(py&7))) { return 0u; }
                        }
                    }
                }
            }
        }
    }
    return 1u;
}
static uint8_t Stroke_FindSafe(int32_t prefX,int32_t prefY,int32_t *outX,int32_t *outY)
{
    int32_t r,dx,dy,cx,cy,score,bestScore,bestX,bestY,tdx,tdy,pdx,pdy,oldRadius,searchX,searchY,maxRadius;
    uint8_t found,usePrev,searchFromPrev,pass,passCount;
    usePrev=(uint8_t)(s_hourPosValid && Stroke_PositionClear(s_hourX,s_hourY));
    searchFromPrev=(uint8_t)(s_hourPosValid && !usePrev);
    searchX=searchFromPrev?s_hourX:prefX; searchY=searchFromPrev?s_hourY:prefY;
    bestX=searchX; bestY=searchY; s_hourLastRadius=0u;
    passCount=searchFromPrev?2u:1u;
    found=0u;
    for(pass=0u;pass<passCount;pass++) {
        if(pass>0u) { searchX=prefX; searchY=prefY; usePrev=0u; }
        maxRadius=(searchFromPrev && pass==0u)?6:64;
        for(r=0;r<=maxRadius;r++) {
            found=0u; bestScore=0x7FFFFFFFL;
            if(r==0) {
                cx=searchX; cy=searchY;
                if(Stroke_PositionClear(cx,cy)) {
                    tdx=cx-searchX; tdy=cy-searchY; score=tdx*tdx+tdy*tdy;
                    if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score=score*8+pdx*pdx+pdy*pdy; }
                    bestScore=score; bestX=cx; bestY=cy; found=1u;
                }
            } else {
                for(dx=-r;dx<=r;dx++) {
                    cx=searchX+dx; cy=searchY-r;
                    if(Stroke_PositionClear(cx,cy)) {
                        tdx=cx-searchX; tdy=cy-searchY; score=(tdx*tdx+tdy*tdy)*8;
                        if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score+=pdx*pdx+pdy*pdy; }
                        if(score<bestScore) { bestScore=score; bestX=cx; bestY=cy; found=1u; }
                    }
                    cy=searchY+r;
                    if(Stroke_PositionClear(cx,cy)) {
                        tdx=cx-searchX; tdy=cy-searchY; score=(tdx*tdx+tdy*tdy)*8;
                        if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score+=pdx*pdx+pdy*pdy; }
                        if(score<bestScore) { bestScore=score; bestX=cx; bestY=cy; found=1u; }
                    }
                }
                for(dy=-r+1;dy<r;dy++) {
                    cy=searchY+dy; cx=searchX-r;
                    if(Stroke_PositionClear(cx,cy)) {
                        tdx=cx-searchX; tdy=cy-searchY; score=(tdx*tdx+tdy*tdy)*8;
                        if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score+=pdx*pdx+pdy*pdy; }
                        if(score<bestScore) { bestScore=score; bestX=cx; bestY=cy; found=1u; }
                    }
                    cx=searchX+r;
                    if(Stroke_PositionClear(cx,cy)) {
                        tdx=cx-searchX; tdy=cy-searchY; score=(tdx*tdx+tdy*tdy)*8;
                        if(usePrev) { pdx=cx-s_hourX; pdy=cy-s_hourY; score+=pdx*pdx+pdy*pdy; }
                        if(score<bestScore) { bestScore=score; bestX=cx; bestY=cy; found=1u; }
                    }
                }
            }
            if(found) { s_hourLastRadius=(uint8_t)r; break; }
        }
        if(found) { break; }
    }
    if(!found) { return 0u; }
    if(usePrev) {
        dx=s_hourX-prefX; if(dx<0) { dx=-dx; }
        dy=s_hourY-prefY; if(dy<0) { dy=-dy; }
        oldRadius=(dx>dy)?dx:dy;
        if(oldRadius<=(int32_t)s_hourLastRadius+2) { bestX=s_hourX; bestY=s_hourY; }
    }
    *outX=bestX; *outY=bestY;
    return 1u;
}
static void Stroke_DrawAt(int32_t cx,int32_t cy)
{
    uint8_t slot;
    int32_t y,x,lx,ly,rx,ry;
    uint32_t mask,bit;
    for(slot=0u;slot<2u;slot++) {
        for(y=-2;y<16;y++) {
            mask=s_hOn[slot][y+2];
            if(!mask) { continue; }
            for(x=-3;x<12;x++) {
                bit=1uL<<(x+3);
                if(mask&bit) {
                    lx=-12+(int32_t)slot*15+x; ly=-7+y;
                    rx=Stroke_RotX(lx,ly); ry=Stroke_RotY(lx,ly);
                    OLED_DrawPixel(cx+rx,cy+ry,OLED_WHITE);
                }
            }
        }
    }
}
void Scene_DrawStrokeNum(int32_t cx,int32_t cy,uint8_t v,uint32_t nowMs)
{
    uint8_t w[2],i,canDraw,canMove;
    int32_t dx,dy,sx,sy,nx,ny,tx,ty,curDist,moveDist,bestMoveDist,fromX,fromY;
#if defined(FW_SIMULATOR)
    int32_t x,y;   /* only the simulator's frame snapshot walks the buffer */
#endif
    s_hourLastDrawn=0u;
    w[0]=(uint8_t)(v/10u); w[1]=(uint8_t)(v%10u);
    for(i=0u;i<2u;i++) { if(s_hv[i]!=w[i]) { Stroke_Build(i,w[i]); s_hv[i]=w[i]; } }
    if(!Stroke_FindSafe(cx,cy,&tx,&ty)) { return; }
    canDraw=(uint8_t)(s_hourPosValid && Stroke_PositionClear(s_hourX,s_hourY));
    canMove=(uint8_t)(!s_hourMoveClockValid || (uint32_t)(nowMs-s_hourMoveAt)>=HOUR_MOVE_INTERVAL_MS);
    if(!canDraw) {
        /* A moving hand/ring reached the old glyph: relocate immediately, never overlap. */
        s_hourX=(int16_t)tx; s_hourY=(int16_t)ty; s_hourPosValid=1u;
        s_hourMoveAt=nowMs; s_hourMoveClockValid=1u;
    } else if((tx!=s_hourX || ty!=s_hourY) && canMove) {
        fromX=s_hourX; fromY=s_hourY;
        dx=tx-s_hourX; dy=ty-s_hourY;
        sx=(dx>0)?1:((dx<0)?-1:0); sy=(dy>0)?1:((dy<0)?-1:0);
        curDist=dx*dx+dy*dy; bestMoveDist=curDist;
        nx=s_hourX+sx; ny=s_hourY+sy;
        if((sx || sy) && Stroke_PositionClear(nx,ny)) { moveDist=(tx-nx)*(tx-nx)+(ty-ny)*(ty-ny); if(moveDist<bestMoveDist) { bestMoveDist=moveDist; s_hourX=(int16_t)nx; s_hourY=(int16_t)ny; } }
        if(bestMoveDist==curDist && sx) {
            nx=s_hourX+sx; ny=s_hourY;
            if(Stroke_PositionClear(nx,ny)) { moveDist=(tx-nx)*(tx-nx)+(ty-ny)*(ty-ny); if(moveDist<bestMoveDist) { bestMoveDist=moveDist; s_hourX=(int16_t)nx; s_hourY=(int16_t)ny; } }
        }
        if(bestMoveDist==curDist && sy) {
            nx=s_hourX; ny=s_hourY+sy;
            if(Stroke_PositionClear(nx,ny)) { moveDist=(tx-nx)*(tx-nx)+(ty-ny)*(ty-ny); if(moveDist<bestMoveDist) { bestMoveDist=moveDist; s_hourX=(int16_t)nx; s_hourY=(int16_t)ny; } }
        }
        if(s_hourX!=fromX || s_hourY!=fromY) { s_hourMoveAt=nowMs; s_hourMoveClockValid=1u; }
    }
    if(Stroke_PositionClear(s_hourX,s_hourY)) {
#if defined(FW_SIMULATOR)
        for(y=0;y<OLED_H/8;y++) { for(x=0;x<OLED_W;x++) { s_hourBase[y][x]=OLED_GRAM[y][x]; } }
#endif
        Stroke_DrawAt(s_hourX,s_hourY);
        s_hourLastDrawn=1u;
    }
}
#if defined(FW_SIMULATOR)
__attribute__((export_name("fw_hour_info"))) uint32_t Scene_DebugHourInfo(void)
{
    return ((uint32_t)(uint8_t)s_hourX) | ((uint32_t)(uint8_t)s_hourY<<8) |
           ((uint32_t)s_hourLastDrawn<<16) | ((uint32_t)(s_hourLastRadius&0x7Fu)<<17);
}
__attribute__((export_name("fw_hour_checks"))) uint32_t Scene_DebugHourChecks(void) { return s_hourClearTests; }
__attribute__((export_name("fw_hour_base_ptr"))) uint32_t Scene_DebugHourBasePtr(void) { return (uint32_t)(uintptr_t)&s_hourBase[0][0]; }
#endif
static uint8_t Background(int32_t u,int32_t v,uint32_t q,int32_t phase)
{
    int32_t base,band,light=0,ad,tail;
    if(q>=65536u && q<196608u) {
        if(q<71536u) { light=255; } else {
            base=170-(int32_t)((q-65536u)*140u/131072u); band=((int32_t)OLED_Isqrt(q)+((u*v)>>7)-phase)&31;
            light=(band<5)?base+55:base/3;
        }
    }
    if(u<0 && u>-80) {
        ad=(v-8)*8; if(ad<0) { ad=-ad; }
        if(ad<18) { tail=220*(18-ad)*(80+u)/1440; if(((u-phase)&15)>3) { tail=tail*3/4; } if(tail>light) { light=tail; } }
    }
    return (uint8_t)light;
}
static uint8_t Fmt_Temp(char *b,int16_t t,uint8_t valid)
{
    uint8_t n=0u;
    int32_t v=t;
    uint32_t ip;
    if(!valid || v < -550 || v > 1250) { b[0]='-'; b[1]='-'; b[2]='.'; b[3]='-'; b[4]=0; return 4u; }
    if(v<0) { b[n++]='-'; v=-v; } ip=(uint32_t)(v/10);
    if(ip>=100u) { b[n++]=(char)('0'+(ip/100u)%10u); } if(ip>=10u) { b[n++]=(char)('0'+(ip/10u)%10u); }
    b[n++]=(char)('0'+ip%10u); b[n++]='.'; b[n++]=(char)('0'+v%10); b[n]=0; return n;
}
static void DrawInfo(const SceneInfo *info)
{
    char b[8];
    uint8_t n;
    uint16_t y;
    if(!info) { return; } OLED_FillRect(0,0,SCENE_INFO_W,SCENE_INFO_H,OLED_BLACK); y=info->year;
    b[0]=(char)('0'+(y/1000u)%10u); b[1]=(char)('0'+(y/100u)%10u); b[2]=(char)('0'+(y/10u)%10u); b[3]=(char)('0'+y%10u); b[4]=0;
    OLED_ShowString(2,3,b,OLED_WHITE);
    b[0]=(char)('0'+info->month/10u); b[1]=(char)('0'+info->month%10u); b[2]='.'; b[3]=(char)('0'+info->day/10u); b[4]=(char)('0'+info->day%10u); b[5]=0;
    OLED_ShowString(2,13,b,OLED_WHITE); OLED_FillRect(2,24,25,9,OLED_WHITE); OLED_ShowString(6,25,s_week[info->weekday%7u],OLED_BLACK);
    OLED_DrawHLine(2,36,29,OLED_WHITE); n=Fmt_Temp(b,info->tempTenths,info->tempValid);
    OLED_ShowString(2,39,b,OLED_WHITE); OLED_DrawRect(2+6*(int32_t)n,39,3,3,OLED_WHITE); OLED_ShowChar(6+6*(int32_t)n,39,'C',OLED_WHITE);
}
void Scene_BlackHole(uint32_t tMs,uint32_t msOfDay,const SceneInfo *info)
{
    int32_t x,y,dx,dy,u,v,un,vn,pixel,c,gx,gy,phase;
    uint32_t q;
    uint8_t hh=(uint8_t)((msOfDay/3600000u)%24u),mm=(uint8_t)((msOfDay/60000u)%60u),ss=(uint8_t)((msOfDay/1000u)%60u),light,threshold,sd;
    phase=(int32_t)((tMs/40u)&31u); Digits_Update(hh,mm); OLED_Clear();
    for(y=0;y<64;y++) { for(x=0;x<128;x++) {
        dx=x-SCENE_CX; dy=y-SCENE_CY; u=(dx*SCENE_COS-dy*SCENE_SIN)>>8; v=(dx*SCENE_SIN+dy*SCENE_COS)>>8;
        un=u*8; vn=v*10; q=(uint32_t)(un*un+vn*vn); light=TimeArea(u,v)?0u:Background(u,v,q,phase);
        threshold=(uint8_t)(s_bayer[((y&3)<<2)|(x&3)]*16u+8u); pixel=(light>threshold)?1:0;
        c=DigitPixel(0u,u-SCENE_HOUR_X,v-SCENE_HOUR_Y); if(c>=0) { pixel=c; }
        c=DigitPixel(1u,u-SCENE_HOUR_X-SCENE_DIG_PITCH,v-SCENE_HOUR_Y); if(c>=0) { pixel=c; }
        c=DigitPixel(2u,u-SCENE_MIN_X,v-SCENE_MIN_Y); if(c>=0) { pixel=c; }
        c=DigitPixel(3u,u-SCENE_MIN_X-SCENE_DIG_PITCH,v-SCENE_MIN_Y); if(c>=0) { pixel=c; }
        gx=u-SCENE_SEC_X; gy=v-SCENE_SEC_Y;
        if(gx>=0 && gx<12 && gy>=0 && gy<7) { sd=(uint8_t)((gx<6)?ss/10u:ss%10u); pixel=(gx%6<5)?((s_small[sd][gx%6]>>gy)&1u):0; }
        if(pixel) { OLED_DrawPixel(x,y,OLED_WHITE); }
    } }
    for(c=0;c<4;c++) { OLED_DrawPixel(s_star[c][0],s_star[c][1],OLED_WHITE); } DrawInfo(info);
}
/* ===========================================================================
 * V20 countdown panel  ("铃声界面")  --  password-lock (drum) style
 * ---------------------------------------------------------------------------
 * Layout: black background, white 1-pixel drawing only.
 *
 *      ┌───────────┐   ┌───────────┐   ┌───────────┐   ┌─────────────┐
 *      │    0 9    │   │    5 8    │   │    3 4    │   │             │
 *      │   1 0     │ : │   5 9     │ : │   3 5     │   │    Start    │
 *      │    1 1    │   │    0 0    │   │    3 6    │   │             │
 *      └───────────┘   └───────────┘   └───────────┘   └─────────────┘
 *         时 00-99         分 00-59         秒 00-59       Start / %
 *                                                       23:59 <- live clock
 *
 *  - the middle row is the value being edited (large digit), the rows above and
 *    below show the neighbouring values (small digits) exactly like a
 *    combination lock / drum; they wrap (59 -> 00) together with the carries
 *  - a value change rolls the drum for PN_ROLL_MS; the digits slide and the one
 *    reaching the centre grows, so the panel feels like a real picker
 *  - the four frames are all exactly the same height and aligned; the selected
 *    frame blinks, the digits inside never blink
 *  - the digits are drawn from one CONNECTED stroke font (2 px round strokes
 *    for the middle row, 1 px for the small rows): no stroke of any digit is
 *    ever broken - there is a self test that checks every digit is a single
 *    connected shape at both sizes
 *  - nothing but "Start" is written on the screen (plus the small live clock)
 * =========================================================================== */
#define PN_BOX_Y0    12                 /* frames: y = 12..59, all four equal */
#define PN_BOX_Y1    59
#define PN_BOX_H     (PN_BOX_Y1-PN_BOX_Y0+1)     /* 48 */
#define PN_BOX_W     25                 /* number frame width                */
#define PN_BOX_B1    1                  /* hour   frame  x = 1..25           */
#define PN_BOX_B2    32                 /* minute frame  x = 32..56          */
#define PN_BOX_B3    63                 /* second frame  x = 63..87          */
#define PN_BOX_B4    94                 /* Start  frame  x = 94..126         */
#define PN_BOX_B4W   33
#define PN_RADIUS    7                  /* obtuse (rounded) corners          */
#define PN_CY0       19                 /* drum row centres: 19 / 36 / 53    */
#define PN_CY1       36
#define PN_CY2       53
#define PN_PITCH     17                 /* row pitch = 17 px (drum geometry) */
#define PN_BLINK_MS  400u               /* selected-frame blink half period  */
#define PN_ROLL_MS   140u               /* drum roll duration after a change */
#define PN_BAR_Y     61                 /* progress bar (running view)       */
#define PN_BAR_X0    2
#define PN_BAR_X1    125

/* ---------------- connected stroke digit font ------------------------------
 * Glyph space: x = 0..20, y = 0..40 in HALF pixels (a 10x20 px cell at scale
 * 1). Every digit is defined by polylines; a digit made of two polylines has
 * them crossing, so the rendered ink is one single connected shape. Zooming to
 * the small rows is a 0.5 coordinate scale plus a pixel-centre snap, which
 * keeps the 1 px strokes crisp and still connected. */
typedef struct { int8_t x,y; } PanelPt;
typedef struct { const PanelPt *p; uint8_t n; } PanelPath;
typedef struct { const PanelPath *paths; uint8_t n; } PanelGlyph;

static const PanelPt pnP0[] = {{2,6},{6,2},{14,2},{18,6},{18,34},{14,38},{6,38},{2,34},{2,6}};
static const PanelPt pnP1a[] = {{8,6},{14,2},{14,38}};
static const PanelPt pnP1b[] = {{6,38},{18,38}};
static const PanelPt pnP2[] = {{2,6},{6,2},{14,2},{18,6},{18,13},{3,38},{18,38}};
static const PanelPt pnP3[] = {{3,3},{7,2},{13,2},{18,7},{18,13},{11,19},{10,20},{11,21},{18,27},{18,33},{13,38},{7,38},{2,36}};
static const PanelPt pnP4a[] = {{13,2},{2,25},{18,25}};
static const PanelPt pnP4b[] = {{13,2},{13,38}};
static const PanelPt pnP5[] = {{18,2},{2,2},{2,17},{12,13},{18,18},{18,34},{13,38},{6,38},{2,35}};
static const PanelPt pnP6[] = {{15,2},{6,3},{2,10},{2,32},{6,38},{13,38},{18,32},{18,26},{13,21},{7,21},{2,26}};
static const PanelPt pnP7[] = {{2,2},{18,2},{7,38}};
static const PanelPt pnP8a[] = {{6,2},{14,2},{18,6},{18,14},{14,20},{6,20},{2,14},{2,6},{6,2}};
static const PanelPt pnP8b[] = {{6,20},{14,20},{18,26},{18,34},{14,38},{6,38},{2,34},{2,26},{6,20}};
static const PanelPt pnP9[] = {{5,38},{12,37},{18,30},{18,8},{14,2},{7,2},{2,7},{2,14},{6,20},{12,20},{18,15}};

static const PanelPath pnG0[1]={{pnP0,9}};
static const PanelPath pnG1[2]={{pnP1a,3},{pnP1b,2}};
static const PanelPath pnG2[1]={{pnP2,7}};
static const PanelPath pnG3[1]={{pnP3,13}};
static const PanelPath pnG4[2]={{pnP4a,3},{pnP4b,2}};
static const PanelPath pnG5[1]={{pnP5,9}};
static const PanelPath pnG6[1]={{pnP6,11}};
static const PanelPath pnG7[1]={{pnP7,3}};
static const PanelPath pnG8[2]={{pnP8a,9},{pnP8b,9}};
static const PanelPath pnG9[1]={{pnP9,11}};
static const PanelGlyph s_pnGlyph[10]={
    {pnG0,1},{pnG1,2},{pnG2,1},{pnG3,1},{pnG4,2},{pnG5,1},{pnG6,1},{pnG7,1},{pnG8,2},{pnG9,1}
};
/* One glyph. ox/oy = top-left corner of the digit cell in screen pixels.
 * small=0: 10x20 px cell, 2 px round strokes.
 * small=1: 6x11 px cell, 1 px strokes snapped to the pixel centres. */
static void Panel_Glyph(int32_t ox,int32_t oy,uint8_t d,uint8_t small)
{
    const PanelGlyph *g;
    uint8_t pi,k;
    if(d>9u) { return; }
    g=&s_pnGlyph[d];
    for(pi=0u;pi<g->n;pi++) {
        const PanelPath *p=&g->paths[pi];
        for(k=0u;k+1u<p->n;k++) {
            int32_t x0,y0,x1,y1,r;
            if(!small) {
                x0=ox*256+(int32_t)p->p[k].x*128;   y0=oy*256+(int32_t)p->p[k].y*128;
                x1=ox*256+(int32_t)p->p[k+1].x*128; y1=oy*256+(int32_t)p->p[k+1].y*128;
                r=128;
            } else {
                /* half scale: 5 px wide, 9 px tall; the vertical map is slightly
                 * compressed so the small rows keep a 2 px air gap to the large
                 * digits above and below them */
                x0=(ox+(((int32_t)p->p[k].x+2)>>2))*256+128;         y0=(oy+1+(((int32_t)p->p[k].y*7+16)>>5))*256+128;
                x1=(ox+(((int32_t)p->p[k+1].x+2)>>2))*256+128;       y1=(oy+1+(((int32_t)p->p[k+1].y*7+16)>>5))*256+128;
                r=0;
            }
            OLED_DrawBrushSegQ8(x0,y0,r,x1,y1,r,OLED_WHITE);
        }
    }
}
/* One drum row: the two digits of a value, centred in the frame. */
static void Panel_Row(int32_t fx0,int32_t fw,int32_t cy,uint8_t v,uint8_t small)
{
    int32_t inner_x=fx0+2,inner_w=fw-4,ox;
    if(v>99u) { v=99u; }
    if(!small) {
        ox=inner_x+(inner_w-21)/2;
        Panel_Glyph(ox,cy-10,(uint8_t)(v/10u),0u);
        Panel_Glyph(ox+11,cy-10,(uint8_t)(v%10u),0u);
    } else {
        ox=inner_x+(inner_w-13)/2;
        Panel_Glyph(ox,cy-5,(uint8_t)(v/10u),1u);
        Panel_Glyph(ox+7,cy-5,(uint8_t)(v%10u),1u);
    }
}
/* ---------------- frames / clock / text ---------------------------------- */
static void Panel_BoxFrame(uint8_t idx,uint8_t selected,uint8_t blinkOn)
{
    int32_t x0,w;
    if(idx==0u) { x0=PN_BOX_B1; w=PN_BOX_W; }
    else if(idx==1u) { x0=PN_BOX_B2; w=PN_BOX_W; }
    else if(idx==2u) { x0=PN_BOX_B3; w=PN_BOX_W; }
    else { x0=PN_BOX_B4; w=PN_BOX_B4W; }
    if(!selected || blinkOn) { OLED_DrawRoundRect(x0,PN_BOX_Y0,x0+w-1,PN_BOX_Y1,PN_RADIUS,OLED_WHITE); }
}
static void Panel_Colons(void)
{
    OLED_FillRect(28,30,2,2,OLED_WHITE); OLED_FillRect(28,40,2,2,OLED_WHITE);
    OLED_FillRect(59,30,2,2,OLED_WHITE); OLED_FillRect(59,40,2,2,OLED_WHITE);
}
/* small live clock, right aligned in the top right corner ("HH:MM") */
static void Panel_Clock(uint32_t msOfDay)
{
    char b[6];
    uint8_t hh=(uint8_t)((msOfDay/3600000u)%24u),mm=(uint8_t)((msOfDay/60000u)%60u);
    b[0]=(char)('0'+hh/10u); b[1]=(char)('0'+hh%10u); b[2]=':';
    b[3]=(char)('0'+mm/10u); b[4]=(char)('0'+mm%10u); b[5]=0;
    OLED_ShowString(98,1,b,OLED_WHITE);
}
static void Panel_Base(uint32_t msOfDay) { OLED_Clear(); Panel_Clock(msOfDay); Panel_Colons(); }
static void Panel_CentreText(int32_t x0,int32_t w,const char *t)
{
    int32_t n=0;
    while(t[n]) { n++; }
    OLED_ShowString(x0+(w-(n*6-1))/2,PN_BOX_Y0+(PN_BOX_H-8)/2,t,OLED_WHITE);
}
/* ---------------- drum state (self-contained in Scene.c) ------------------ */
static uint8_t s_pnPrev[3]={0xFFu,0xFFu,0xFFu};
static uint8_t s_pnDir[3]={0u,0u,0u};
static uint32_t s_pnRollAt[3]={0u,0u,0u};
/* Wrap around the field range: hour 0..99, minute/second 0..59. */
static uint8_t Panel_Wrap(uint8_t field,int32_t v)
{
    int32_t lo=(field==0u)?100:60;
    v%=lo; if(v<0) { v+=lo; }
    return (uint8_t)v;
}
/* Draw the drum of one number frame: the value `v` sits in the middle row, the
 * neighbours above/below are the small candidates, and while a change is being
 * animated every row slides by the same amount (clipped to the frame). */
static void Panel_Drum(int32_t fx0,uint8_t fw,uint8_t field,uint32_t tMs,uint8_t v,uint8_t selected,uint8_t blinkOn)
{
    int32_t i,j,off=0,n=0;
    int32_t ys[4],ad[4],order[4];
    uint8_t ws[4];
    uint32_t el;
    if(s_pnPrev[field]!=v) {
        if(s_pnPrev[field]==0xFFu) { s_pnDir[field]=0u; }
        else {
            int32_t lo=(field==0u)?100:60;
            int32_t d=(int32_t)v-(int32_t)s_pnPrev[field];
            if(d<0) { d+=lo; }
            /* d==0 cannot happen here; small d = value grew, large d = shrank */
            s_pnDir[field]=(uint8_t)((d*2<=lo)?1u:2u);
        }
        s_pnPrev[field]=v; s_pnRollAt[field]=tMs+1u;
    }
    if(s_pnRollAt[field]!=0u) {
        el=(uint32_t)(tMs-(s_pnRollAt[field]-1u));
        if(el>=PN_ROLL_MS) { s_pnRollAt[field]=0u; }
        else { off=(int32_t)(PN_PITCH*(PN_ROLL_MS-el)/PN_ROLL_MS); }
    }
    Panel_BoxFrame(field,selected,blinkOn);
    OLED_SetClipRect(fx0+1,PN_BOX_Y0+1,fx0+(int32_t)fw-2,PN_BOX_Y1-1);
    if(off==0) {
        /* settled: neighbours above/below are the candidate values */
        Panel_Row(fx0,fw,PN_CY0,Panel_Wrap(field,(int32_t)v-1),1u);
        Panel_Row(fx0,fw,PN_CY2,Panel_Wrap(field,(int32_t)v+1),1u);
        Panel_Row(fx0,fw,PN_CY1,v,0u);
    } else {
        /* rolling: every row slides by the same amount; the row that reaches
         * the centre becomes the large one, so the value appears to grow */
        if(s_pnDir[field]==1u) {
            for(i=0;i<4;i++) {
                int32_t w=(int32_t)v-2+i;
                ws[n]=Panel_Wrap(field,w);
                ys[n]=PN_CY1+(w-(int32_t)v)*PN_PITCH+off;
                n++;
            }
        } else {
            for(i=0;i<4;i++) {
                int32_t w=(int32_t)v-1+i;
                ws[n]=Panel_Wrap(field,w);
                ys[n]=PN_CY1+(w-(int32_t)v)*PN_PITCH-off;
                n++;
            }
        }
        for(i=0;i<n;i++) { ad[i]=ys[i]-PN_CY1; if(ad[i]<0) { ad[i]=-ad[i]; } }
        for(i=0;i<n;i++) {
            int32_t best=-1;
            for(j=0;j<n;j++) { if(ad[j]<0) { continue; } if(best<0 || ad[j]>ad[best]) { best=j; } }
            order[i]=best; ad[best]=-1;
        }
        for(i=0;i<n;i++) {
            int32_t d=ys[order[i]]-PN_CY1;
            if(d<0) { d=-d; }
            Panel_Row(fx0,fw,ys[order[i]],ws[order[i]],(uint8_t)((d*2>=PN_PITCH)?1u:0u));
        }
    }
    OLED_SetClipRect(0,0,-1,-1);
}
/* Snap all three drums (no roll) - called when the panel is (re)entered so the
 * first drawn frame is always the settled state. */
void Scene_TimerPanelReset(void)
{
    s_pnPrev[0]=0xFFu; s_pnPrev[1]=0xFFu; s_pnPrev[2]=0xFFu;
    s_pnDir[0]=0u; s_pnDir[1]=0u; s_pnDir[2]=0u;
    s_pnRollAt[0]=0u; s_pnRollAt[1]=0u; s_pnRollAt[2]=0u;
}
/* ---------------- public API -------------------------------------------- */
/* Setup screen: 时/分/秒 drums + Start, small live clock, nothing else. */
void Scene_TimerPanel(uint32_t tMs,uint32_t msOfDay,uint8_t h,uint8_t m,uint8_t s,uint8_t selected)
{
    uint8_t blinkOn=(uint8_t)(((tMs/PN_BLINK_MS)&1u)==0u);
    Panel_Base(msOfDay);
    Panel_Drum(PN_BOX_B1,PN_BOX_W,0u,tMs,h,(uint8_t)(selected==0u),blinkOn);
    Panel_Drum(PN_BOX_B2,PN_BOX_W,1u,tMs,m,(uint8_t)(selected==1u),blinkOn);
    Panel_Drum(PN_BOX_B3,PN_BOX_W,2u,tMs,s,(uint8_t)(selected==2u),blinkOn);
    Panel_BoxFrame(3u,(uint8_t)(selected==3u),blinkOn);
    Panel_CentreText(PN_BOX_B4,PN_BOX_B4W,"Start");
}
/* Running screen: remaining time (large digits, no drum), remaining percentage
 * in the 4th frame and a 1 px progress bar below the frames. */
void Scene_TimerRunning(uint32_t msOfDay,uint32_t remainMs,uint32_t pct)
{
    char b[5];
    uint8_t hh=(uint8_t)(remainMs/3600000u),mm=(uint8_t)((remainMs/60000u)%60u),ss=(uint8_t)((remainMs/1000u)%60u);
    uint32_t left,w;
    int32_t x;
    if(hh>99u) { hh=99u; }
    if(pct>1000u) { pct=1000u; }
    left=(1000u-pct+5u)/10u;
    Panel_Base(msOfDay);
    Panel_BoxFrame(0u,0u,1u); Panel_BoxFrame(1u,0u,1u); Panel_BoxFrame(2u,0u,1u); Panel_BoxFrame(3u,0u,1u);
    Panel_Row(PN_BOX_B1,PN_BOX_W,PN_CY1,hh,0u);
    Panel_Row(PN_BOX_B2,PN_BOX_W,PN_CY1,mm,0u);
    Panel_Row(PN_BOX_B3,PN_BOX_W,PN_CY1,ss,0u);
    if(left>=100u) { b[0]='1'; b[1]='0'; b[2]='0'; b[3]='%'; b[4]=0; }
    else if(left>=10u) { b[0]=(char)('0'+left/10u); b[1]=(char)('0'+left%10u); b[2]='%'; b[3]=0; }
    else { b[0]=(char)('0'+left); b[1]='%'; b[2]=0; }
    Panel_CentreText(PN_BOX_B4,PN_BOX_B4W,b);
    for(x=PN_BAR_X0;x<=PN_BAR_X1;x+=4) { OLED_DrawPixel(x,PN_BAR_Y,OLED_WHITE); }
    w=(uint32_t)(pct*(uint32_t)(PN_BAR_X1-PN_BAR_X0)/1000u);
    if(w>0u) { OLED_DrawHLine(PN_BAR_X0,PN_BAR_Y,(int32_t)w,OLED_WHITE); }
}



/* ===========================================================================
 * V30 游戏模块: 游戏选择界面 + 俄罗斯方块
 * ---------------------------------------------------------------------------
 * 中文标题用 16x16 点阵 (Noto Sans SC 400 权重, 4x 超采样后按 110/255 二值化,
 * 笔画最清楚; 12x12 会把"俄罗斯"糊成一团)。7 个字共 224 B。
 *
 * 选择界面 (128x64):
 *   y=2 ..29  [跳一跳   细线框] [跳跃图标]
 *   y=34..61  [俄罗斯方块 细线框] [方块图标]
 *   选中项的外框 400ms 闪烁; PA4 切换, PA5 进入, 长按 PA4 2 秒回时间界面。
 *
 * 俄罗斯方块:
 *   x=0..31  游戏区  10 列 x 20 行, 每格 3px, 1px 细线外框
 *   x=35..127 右边框 上半 = 下一个方块 (4x4 网格, 每格 6px), 下半 = 得分
 * =========================================================================== */
#define G_BLINK_MS 400u

/* 16x16 点阵: 跳 一 俄 罗 斯 方 块 (行优先, 每行 2 字节, 高位在左) */
static const uint8_t s_gCjk[6][32]={
    {0x00,0x00,0x3C,0x58,0x7C,0x58,0x67,0x5A,0x65,0x5E,0x7D,0xDC,0x18,0x58,0x18,0x58,0x5C,0xDC,0x59,0xDE,0x5B,0x5A,0x58,0xD8,0x7E,0x98,0x71,0x9B,0x03,0x0E,0x00,0x00},   /* 跳 */
    {0x00,0x00,0x18,0xF4,0x1F,0xB4,0x11,0x32,0x31,0x10,0x77,0xFE,0x77,0xFE,0xF1,0x10,0x31,0x14,0x33,0xDC,0x3F,0x18,0x31,0x18,0x31,0x3A,0x31,0x6A,0x37,0x4E,0x00,0x00},   /* 俄 */
    {0x00,0x00,0x3F,0xFC,0x26,0x44,0x26,0x44,0x3F,0xFC,0x3F,0xFC,0x06,0x00,0x0F,0xF8,0x18,0x18,0x34,0x18,0x02,0x30,0x01,0xE0,0x01,0x80,0x0F,0x00,0x78,0x00,0x00,0x00},   /* 罗 */
    {0x00,0x00,0x22,0x0E,0x33,0x70,0x7F,0x40,0x22,0x40,0x3E,0x40,0x22,0x7F,0x32,0x44,0x3E,0x44,0x22,0x44,0x7F,0xC4,0x14,0xC4,0x36,0xC4,0x22,0x84,0x41,0x84,0x00,0x00},   /* 斯 */
    {0x00,0x00,0x01,0x80,0x00,0x80,0x7F,0xFE,0x7F,0xFE,0x06,0x00,0x06,0x00,0x07,0xF8,0x06,0x08,0x04,0x08,0x0C,0x08,0x08,0x08,0x18,0x08,0x30,0x18,0x60,0xF0,0x00,0x00},   /* 方 */
    {0x00,0x00,0x10,0x60,0x10,0x60,0x13,0xFC,0x78,0x6C,0x78,0x64,0x10,0x64,0x10,0x64,0x13,0xFE,0x10,0x60,0x3C,0x70,0x70,0xD0,0x01,0x98,0x03,0x0C,0x06,0x06,0x00,0x00},   /* 块 */
};
/* 字库索引: "跳一跳"=0,1,0  "俄罗斯方块"=2,3,4,5,6 */
static const uint8_t s_gName1[3]={0u,1u,0u};
static const uint8_t s_gName2[5]={2u,3u,4u,5u,6u};

/* 画一个 16x16 汉字 */
/* V30: 通用 1-bit 图标 (w x h, 每行字节对齐)。游戏选择界面和结算界面共用。
 * 位图由模拟器渲染结果逐像素导出, 与早期用绘图原语拼出来的形状**完全一致**,
 * 但把 ~380 B 的绘图代码换成了 208 B 的只读数据。 */
static void G_Ico(int32_t x,int32_t y,const uint8_t *b,uint8_t w,uint8_t h)
{
    uint8_t r,c,bw=(uint8_t)((w+7u)>>3);
    for(r=0u;r<h;r++) {
        for(c=0u;c<w;c++) {
            if(b[(uint16_t)r*bw+(c>>3)] & (uint8_t)(0x80u>>(c&7))) { OLED_DrawPixel(x+c,y+r,OLED_WHITE); }
        }
    }
}
static const uint8_t s_gIcoJump[112]={
    0x00,0x00,0x07,0x00,0x00,0x00,0x07,0x00,0x00,0x00,0x07,0x00,
    0x00,0x00,0x00,0x00,0x00,0x00,0x02,0x00,0x00,0x00,0x02,0x00,
    0x00,0x00,0x07,0x00,0x00,0x00,0x0A,0x80,0x00,0x00,0x12,0x40,
    0x00,0x00,0x02,0x00,0x00,0x00,0x02,0x00,0x00,0x00,0x05,0x00,
    0x00,0x00,0x04,0x80,0x00,0x00,0x08,0x40,0x00,0x00,0x08,0x00,
    0x00,0x1E,0x00,0x00,0x00,0x21,0x00,0x00,0x00,0x40,0x80,0x00,
    0x00,0x80,0x20,0x00,0x00,0x00,0x00,0x00,0x01,0xE0,0x00,0x00,
    0x01,0xE0,0x00,0x00,0x00,0xFF,0xF0,0x00,0x00,0xFF,0xF0,0x00,
    0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
    0x00,0x00,0x00,0x00
};
static const uint8_t s_gIcoTet[96]={
    0x00,0x00,0x00,0x00,0x00,0x00,0x0F,0x80,0x7D,0xF7,0xCF,0x80,
    0x7D,0xF7,0xCF,0x80,0x7D,0xF7,0xCF,0x80,0x7D,0xF7,0xCF,0x80,
    0x7D,0xF7,0xC0,0x00,0x00,0x00,0x0F,0x80,0x01,0xF0,0x0F,0x80,
    0x01,0xF0,0x0F,0x80,0x01,0xF0,0x0F,0x80,0x01,0xF0,0x0F,0x80,
    0x01,0xF0,0x00,0x00,0x00,0x00,0x0F,0x80,0x00,0x00,0x0F,0x80,
    0x00,0x00,0x0F,0x80,0x00,0x00,0x0F,0x80,0x00,0x00,0x0F,0x80,
    0x00,0x00,0x00,0x00,0x00,0x00,0x0F,0xBE,0x00,0x00,0x0F,0xBE,
    0x00,0x00,0x0F,0xBE,0x00,0x00,0x0F,0xBE,0x00,0x00,0x0F,0xBE
};
static void G_Cjk(int32_t x,int32_t y,uint8_t idx)
{
    int32_t r,c;
    const uint8_t *g;
    if(idx>6u) { return; }
    if(idx==1u) { OLED_DrawHLine(x+1,y+8,14,OLED_WHITE); return; }  /* "一" = 一条横线, 省 32 B */
    g=s_gCjk[idx>1u?(idx-1u):idx];
    for(r=0;r<16;r++) {
        uint16_t bits=(uint16_t)(((uint16_t)g[r*2]<<8)|g[r*2+1]);
        for(c=0;c<16;c++) {
            if(bits & (uint16_t)(0x8000u>>c)) { OLED_DrawPixel(x+c,y+r,OLED_WHITE); }
        }
    }
}
static void G_Str(int32_t x,int32_t y,const uint8_t *s,uint8_t n)
{
    uint8_t i;
    for(i=0u;i<n;i++) { G_Cjk(x+(int32_t)i*16,y,s[i]); }
}

/* 钝角细线框 (1px) —— 与设置界面的方框同一造型, 半径 2 */
static void G_Box(int32_t x0,int32_t y0,int32_t x1,int32_t y1,uint8_t on)
{
    OLED_DrawRoundRect(x0,y0,x1,y1,2,on?OLED_WHITE:OLED_BLACK);
}

/* ---- 游戏选择界面 ------------------------------------------------------ */
void Scene_GameMenu(uint32_t tMs,uint8_t sel)
{
    uint8_t blinkOn=(uint8_t)(((tMs/G_BLINK_MS)&1u)==0u);
    OLED_Clear();
    /* V30: 两行都用**整屏宽**的细线钝角框, 文字在左、自绘图标在右,
     * 这样两行长度一致, 视觉上是一张列表而不是两个长短不一的卡片。 */
    G_Box(0,1,127,30,(uint8_t)(sel!=0u || blinkOn));
    G_Str(2,8,s_gName1,3u);
    G_Ico(99,2,s_gIcoJump,26u,28u);
    G_Box(0,33,127,62,(uint8_t)(sel==0u || blinkOn));
    G_Str(2,40,s_gName2,5u);
    G_Ico(93,37,s_gIcoTet,32u,24u);
}


/* ---- 俄罗斯方块: 绘制 --------------------------------------------------- */
/* V31 游戏区几何: 10 列 x 20 行, 每格 **6 宽 x 3 高**。
 * 为什么不是方格子: 20 行要装进 64px 高度, 方格子上限就是 3px -> 只有 30px 宽,
 * 左框永远比右框窄。改成 6x3 后场地 60x60, 左框能做到 72px (右框 55px),
 * 满足"左边的框比右边的框大"; 每格填 5x2px 留 1px 缝, 视觉上是整齐的砖墙。
 *   左外框 x=0..71, y=1..62    右外框 x=73..127, y=1..62
 *   格子 (c,r) -> x=6+c*6, y=2+r*3                                */
#define GT_CW    6
#define GT_CH    3
#define GT_FX    6
#define GT_FY    2
#define GT_COLS  10
#define GT_ROWS  20
#define GT_LX1   71        /* 左框右边线 */
#define GT_IX0   73        /* 右框左边线 */
#define GT_IX1   127

/* 3x5 数字点阵 (0..9), 用于得分 / 倒数 */
static const uint8_t s_gDig[10][5]={
    {0x7u,0x5u,0x5u,0x5u,0x7u},{0x2u,0x6u,0x2u,0x2u,0x7u},
    {0x7u,0x1u,0x7u,0x4u,0x7u},{0x7u,0x1u,0x7u,0x1u,0x7u},
    {0x5u,0x5u,0x7u,0x1u,0x1u},{0x7u,0x4u,0x7u,0x1u,0x7u},
    {0x7u,0x4u,0x7u,0x5u,0x7u},{0x7u,0x1u,0x1u,0x1u,0x1u},
    {0x7u,0x5u,0x7u,0x5u,0x7u},{0x7u,0x5u,0x7u,0x1u,0x7u}
};
/* 画一个可缩放的数字 (s=1 -> 3x5) */
static void G_BigDig(int32_t x,int32_t y,uint8_t d,uint8_t s)
{
    int32_t r,c,dy,dx;
    if(d>9u || s==0u) { return; }
    for(r=0;r<5;r++) {
        uint8_t bits=s_gDig[d][r];
        for(c=0;c<3;c++) {
            if(bits & (uint8_t)(4u>>c)) {
                for(dy=0;dy<(int32_t)s;dy++) {
                    for(dx=0;dx<(int32_t)s;dx++) {
                        OLED_DrawPixel(x+c*(int32_t)s+dx,y+r*(int32_t)s+dy,OLED_WHITE);
                    }
                }
            }
        }
    }
}
void Scene_BigDigit(int32_t x,int32_t y,uint8_t d,uint8_t s) { G_BigDig(x,y,d,s); }
static int32_t G_DigW(uint8_t n,uint8_t s) { return (int32_t)n*4*(int32_t)s-(int32_t)s; }
/* 定宽右对齐显示 n 位数字 */
static void G_Num(int32_t x,int32_t y,uint32_t v,uint8_t n,uint8_t s)
{
    uint8_t i;
    uint32_t p=1u;
    for(i=1u;i<n;i++) { p*=10u; }
    for(i=0u;i<n;i++) { G_BigDig(x+(int32_t)i*4*(int32_t)s,y,(uint8_t)((v/p)%10u),s); if(p>=10u) { p/=10u; } }
}
/* 在矩形里居中画一段数字 */
static void G_NumCentre(int32_t x0,int32_t x1,int32_t y,uint32_t v,uint8_t n,uint8_t s)
{
    G_Num(x0+(x1-x0-G_DigW(n,s))/2,y,v,n,s);
}

/* 把一个"方块格"画成 3x3 里带 1px 缝的方块 (游戏区)。
 * 3x3 全填会连成一片白, 看不出是"格子"; 填 3x3 后抠掉右下 1px 又太碎。
 * 实测: 填 3 宽 x 2 高, 底部留 1px 黑缝, 网格感最清楚且不丢亮度。 */
static void GT_Cell(int32_t c,int32_t r,uint8_t on)
{
    int32_t x=GT_FX+c*GT_CW, y=GT_FY+r*GT_CH;
    if(on) { OLED_FillRect(x,y,GT_CW-1,GT_CH-1,OLED_WHITE); }
    else   { OLED_FillRect(x,y,GT_CW,GT_CH,OLED_BLACK); }
}

/* 重画整个游戏区: 按行合并成连续 run, 一帧只发变化的行 */
/* 上一帧画在屏上的内容 (用于增量重画): 20 行的 10 位图 + 右边栏的签名 */
static uint16_t s_gtDrawn[GT_ROWS];
static uint16_t s_gtDrawnSig=0xFFFFu;      /* 右边栏: 下一个方块 + 得分 */
static uint8_t  s_gtDrawnOvl=0xFFu;        /* 暂停/倒数覆盖层 */
static uint8_t  s_gtDrawnCount=0xFFu;
static uint8_t  s_gtFirst=1u;

/* 把一帧要显示的图形算成 20 个 10 位行 */
static void GT_Compose(const uint16_t *board,const uint8_t *cells,uint8_t ncell,uint16_t *out)
{
    int32_t r,i;
    for(r=0;r<GT_ROWS;r++) { out[r]=(uint16_t)(board[r]&0x3FFu); }
    for(i=0;i<(int32_t)ncell;i++) {
        uint8_t c=cells[i*2], rr=cells[i*2+1];
        if(c<(uint8_t)GT_COLS && rr<(uint8_t)GT_ROWS) { out[rr] |= (uint16_t)(1u<<c); }
    }
}

void Scene_Tetris(uint32_t tMs,const uint16_t *board,
                  const uint8_t *cells,uint8_t ncell,
                  uint32_t score,const uint8_t *next,uint8_t nnext,
                  uint8_t paused,uint8_t count)
{
    int32_t r,c;
    uint16_t want[GT_ROWS];
    uint16_t sig;
    uint8_t ovl;
    (void)tMs;

    GT_Compose(board,cells,ncell,want);

    if(s_gtFirst) {
        s_gtFirst=0u;
        G_Box(0,1,GT_LX1,62,1u);
        G_Box(GT_IX0,1,GT_IX1,62,1u);
        for(r=0;r<GT_ROWS;r++) { s_gtDrawn[r]=0xFFFFu; }   /* 强制全部重画 */
    }

    /* ---- 游戏区: 只重画"和上一帧不同"的格子 ---- */
    for(r=0;r<GT_ROWS;r++) {
        uint16_t diff=(uint16_t)(want[r]^s_gtDrawn[r]);
        if(!diff) { continue; }
        for(c=0;c<GT_COLS;c++) {
            if(diff & (uint16_t)(1u<<c)) { GT_Cell(c,r,(uint8_t)((want[r]>>c)&1u)); }
        }
        s_gtDrawn[r]=want[r];
    }

    /* ---- 右边栏签名: 下一个方块 + 得分 + 覆盖层 ---- */
    sig=(uint16_t)((score&0x1FFu)*16u+((nnext>0u)?next[0]:0u));
    /* 下一个方块用完整 4 格做签名 */
    {
        uint32_t h=2166136261u;
        uint8_t i;
        for(i=0u;i<nnext;i++) { h=(h^next[i*2])*16777619u; h=(h^next[i*2+1])*16777619u; }
        h=(h^score)*16777619u;
        sig=(uint16_t)(h&0xFFFFu);
    }
    ovl=(uint8_t)((paused?2u:0u)|((count!=0u)?1u:0u));
    if(sig!=s_gtDrawnSig) {
        s_gtDrawnSig=sig;
        /* 右上: 下一个方块。小方块放在左下, 右上角留一个 1px 细线的小预览框;
         * 方块大小 5px 一格, 归一化后在 [x=GT_IX0+4 .. ] 区间居中。 */
        int32_t bx0=9,by0=9,bx1=0,by1=0,kw,kh,ox,oy;
        int32_t areaX0=GT_IX0+2,areaX1=GT_IX1-2,areaY0=4,areaY1=30;
        for(c=0;c<nnext;c++) {
            int32_t cc=next[c*2], rr=next[c*2+1];
            if(cc<bx0) { bx0=cc; } if(cc>bx1) { bx1=cc; }
            if(rr<by0) { by0=rr; } if(rr>by1) { by1=rr; }
        }
        if(bx1<bx0 || by1<by0) { bx0=by0=0; bx1=by1=0; }
        kw=(bx1-bx0+1)*6-1; kh=(by1-by0+1)*6-1;
        ox=areaX0+(areaX1-areaX0-kw)/2; oy=areaY0+(areaY1-areaY0-kh)/2;
        OLED_FillRect(areaX0,areaY0,areaX1-areaX0+1,areaY1-areaY0+1,OLED_BLACK);
        for(c=0;c<nnext;c++) {
            int32_t cc=next[c*2], rr=next[c*2+1];
            if(cc>3 || rr>3) { continue; }
            /* 预览方块用 1px 描边的"空心"格, 与游戏区的实心砖墙区分开:
             * 小地方用空心反而更清楚, 也省得和得分数字抢视觉。 */
            OLED_DrawRect(ox+((int32_t)cc-bx0)*6,oy+((int32_t)rr-by0)*6,5,5,OLED_WHITE);
        }
        /* 分隔点线 */
        for(c=GT_IX0+3;c<GT_IX1-2;c+=2) { OLED_DrawPixel(c,33,OLED_WHITE); }
        /* 右下: 得分 (5 位, 放大 2 倍) */
        OLED_FillRect(GT_IX0+1,34,GT_IX1-GT_IX0-1,26,OLED_BLACK);
        G_NumCentre(GT_IX0+1,GT_IX1,42,score,5u,2u);
    }

    /* ---- 暂停 / 3-2-1 倒数 (只在游戏区内) ---- */
    if(ovl!=s_gtDrawnOvl || count!=s_gtDrawnCount) {
        int32_t cx=GT_FX+(GT_COLS*GT_CW)/2;
        int32_t cy=GT_FY+(GT_ROWS*GT_CH)/2;
        s_gtDrawnOvl=ovl; s_gtDrawnCount=count;
        OLED_FillRect(GT_FX,cy-12,GT_COLS*GT_CW,25,OLED_BLACK);
        /* 这一条带子是**不透明遮罩**: 暂停/倒数时整条刷黑再画图标, 不补格子。
         * 早先的写法是"先补格子再画图标", 补格子会在两条竖杠中间留下一个
         * 方块缺口 (V30 踩过)。解除暂停时 ovl 变化, 这条带子会重新按 want[]
         * 逐格重画, 所以不会丢内容。 */
        if(count!=0u) {
            uint8_t d=(count>9u)?9u:count;
            if(d==0u) { d=1u; }
            G_BigDig(cx-G_DigW(1u,4u)/2,cy-10,d,4u);
        } else if(paused) {
            OLED_FillRect(cx-6,cy-9,5,18,OLED_WHITE);
            OLED_FillRect(cx+1,cy-9,5,18,OLED_WHITE);
        }
    }
}

/* ===========================================================================
 * V22 秒表界面 (stopwatch screen)  —— 大钟盘做到最大 + 5x9 细腻字体
 * ---------------------------------------------------------------------------
 * 布局 (128x64)：
 *   左边：**大钟盘**（外环 R=31，圆心 (32,32) → 上下各留 1px，贴着 OLED 上下边）
 *         外圈细线圆环 + 60 格刻度（每 5 格加长 6px，其余 3px，都画在环内 1px）
 *         两根针：长针 = 总时间（1px 细线 + 短尾 + 渐细针尖）
 *                 短针 = 分圈进度（**每次分圈从 12 点方向重新开始扫**，一圈 60 秒）
 *   右上：总计时 MM:SS.mmm，5x9 圆角笔画数字字体（1px 笔画，右对齐到 x=127）
 *   右下：4 行分圈记录（行距 12px）—— ①..⑨ 9px 圆环 / ⑩.. 15x9 胶囊 + 该圈用时
 *   屏幕上没有任何中文/英文
 * 流畅度：增量绘制（指针只擦旧画新、数字只重画变化的字符格、列表按签名重画）
 * =========================================================================== */
#define SW_CX        32                  /* 表盘圆心: (32,32) */
#define SW_CY        32
/* 外环半径 31.5px (Q8 8064): 上下左右四个切点正好落在
 * (32,0)/(32,63)/(0,32)/(63,32) 的像素中心上 —— 半径再大一点点,
 * 底部切点就会落到第 64 行(屏外)而被裁掉, 屏幕正中会裂开 1px */
#define SW_RING_Q8   8064
#define SW_R         31.5                /* 外环半径 (px) */
#define SW_TICK_R    30                  /* 刻度外端 (环内留 2px, 环保持干净细圆) */
#define SW_MAJ_R     24                  /* 长刻度内端 (每 5 格, 长 6px) */
#define SW_MIN_R     27                  /* 短刻度内端 (长 3px) */
#define SW_HAND_R    21                  /* 总时间针长度 (擦除后离长刻度还有 2px) */
#define SW_HAND_TAIL 7                   /* 总时间针反向短尾 */
#define SW_LAP_R     16                  /* 分圈针长度 */
#define SW_LAP_TAIL  4
#define SW_HAND_W    128                 /* 针身笔宽 Q8 (半径 1px → 2px 细针) */
#define SW_TIP_W     64                  /* 针尖渐细笔宽 Q8 */
#define SW_CAP_Q8    160                 /* 分圈针端帽 Q8 (圆角, 半径 1.125px) */
#define SW_ERASE_Q8  256                 /* 擦针笔宽 Q8: 半径 1.5px > 针尖 2x2 端帽的
                                          * 1.41px 对角, 否则每帧残留像素会拖出弧形鬼影 */
#define SW_TIMER_X   82                  /* MM:SS.mmm 左端 (46px, 右对齐 127) */
#define SW_TIMER_Y   0
#define SW_ROW_Y0    15                  /* 第一行分圈记录的 y */
#define SW_ROW_PITCH 12
#define SW_ROW_N     4                   /* 一次显示 4 行 */
#define SW_MARK_X0   66                  /* 圈号标记左边界 (胶囊最宽 15px → x=66..80) */
#define SW_VAL_X0    84                  /* 分圈用时左端 (紧跟圈号, 一列对齐) */
#define SW_MARK_R1   4                   /* ①..⑨  : 直径 9 的圆环 */
#define SW_MARK_CAPW 15                  /* ⑩..⑨⑨: 15x9 圆角胶囊 */
#define SW_MARK_CAPH 9
#define SW_BLINK_MS  400u

/* ---- 5x9 圆角笔画数字字体 (1px 细笔画, 每行 5 bit, bit4 = 最左) ---------- */
static const uint8_t s_sw9[10][9]={
    {0x0Eu,0x11u,0x11u,0x11u,0x11u,0x11u,0x11u,0x11u,0x0Eu},   /* 0 */
    {0x04u,0x0Cu,0x04u,0x04u,0x04u,0x04u,0x04u,0x04u,0x0Eu},   /* 1 */
    {0x0Eu,0x11u,0x01u,0x02u,0x04u,0x08u,0x10u,0x10u,0x1Fu},   /* 2 */
    {0x0Eu,0x11u,0x01u,0x01u,0x06u,0x01u,0x01u,0x11u,0x0Eu},   /* 3 */
    {0x02u,0x06u,0x0Au,0x12u,0x12u,0x1Fu,0x02u,0x02u,0x02u},   /* 4 */
    {0x1Fu,0x10u,0x10u,0x10u,0x1Eu,0x01u,0x01u,0x11u,0x0Eu},   /* 5 */
    {0x06u,0x08u,0x10u,0x10u,0x1Eu,0x11u,0x11u,0x11u,0x0Eu},   /* 6 */
    {0x1Fu,0x01u,0x02u,0x02u,0x04u,0x04u,0x08u,0x08u,0x08u},   /* 7 */
    {0x0Eu,0x11u,0x11u,0x11u,0x0Eu,0x11u,0x11u,0x11u,0x0Eu},   /* 8 */
    {0x0Eu,0x11u,0x11u,0x11u,0x0Fu,0x01u,0x01u,0x01u,0x1Eu}    /* 9 */
};
/* ---- 3x5 数字 (分圈圆环里的圈号) --------------------------------------- */
static const uint8_t s_sw5[10][5]={
    {0x6u,0x5u,0x5u,0x5u,0x6u},{0x2u,0x6u,0x2u,0x2u,0x7u},
    {0x6u,0x1u,0x2u,0x4u,0x7u},{0x6u,0x1u,0x2u,0x1u,0x6u},
    {0x5u,0x5u,0x7u,0x1u,0x1u},{0x7u,0x4u,0x6u,0x1u,0x6u},
    {0x6u,0x4u,0x6u,0x5u,0x6u},{0x7u,0x1u,0x2u,0x2u,0x4u},
    {0x6u,0x5u,0x6u,0x5u,0x6u},{0x6u,0x5u,0x7u,0x1u,0x6u}
};
/* 字符宽度: 数字 5(+1 间隔=6), ':' 与 '.' 2 */
static int32_t Sw_ChW(char c) { return (c==':'||c=='.')?2:6; }
/* 画一个 5x9 字符 (color=0 时只用于擦除, 不画) */
static void Sw_DrawCh9(int32_t x,int32_t y,char c,uint8_t color)
{
    uint8_t r,b;
    if(c>='0' && c<='9') {
        const uint8_t *g=s_sw9[(uint8_t)(c-'0')];
        for(r=0u;r<9u;r++) { for(b=0u;b<5u;b++) { if(g[r]&(uint8_t)(16u>>b)) { if(color) { OLED_DrawPixel(x+(int32_t)b,y+(int32_t)r,OLED_WHITE); } } } }
        return;
    }
    if(c==':') { if(color) { OLED_DrawPixel(x,y+2,OLED_WHITE); OLED_DrawPixel(x,y+3,OLED_WHITE);
                              OLED_DrawPixel(x,y+5,OLED_WHITE); OLED_DrawPixel(x,y+6,OLED_WHITE); } return; }
    if(c=='.') { if(color) { OLED_DrawPixel(x,y+8,OLED_WHITE); } return; }
}
static int32_t Sw_Str9(int32_t x,int32_t y,const char *s) { while(*s) { Sw_DrawCh9(x,y,*s,1u); x+=Sw_ChW(*s); s++; } return x; }
static int32_t Sw_W9(const char *s) { int32_t w=0; while(*s) { w+=Sw_ChW(*s); s++; } return w-1; }
/* 把 old 文本变成 new 文本: 只擦/画真正不同的字符格 */
static void Sw_TextDiff9(int32_t x,int32_t y,const char *old,const char *new)
{
    int32_t cx=x,i=0,j=0,w;
    while(old[i] || new[j]) {
        char a=old[i],b=new[j];
        w=Sw_ChW(a?a:b);
        if(a!=b) { OLED_FillRect(cx,y,w,9,OLED_BLACK); Sw_DrawCh9(cx,y,b,1u); }
        cx+=w; if(a) { i++; } if(b) { j++; }
    }
}
static void Sw_Glyph5(int32_t x,int32_t y,uint8_t d)
{
    uint8_t r,b;
    const uint8_t *g=s_sw5[d%10u];
    for(r=0u;r<5u;r++) { for(b=0u;b<3u;b++) { if(g[r]&(uint8_t)(4u>>b)) { OLED_DrawPixel(x+(int32_t)b,y+(int32_t)r,OLED_WHITE); } } }
}
/* ---- 时间格式化 --------------------------------------------------------- */
/* 总计时 "MM:SS.mmm" (分最高 99) */
static void Sw_FmtTotal(char *b,uint32_t ms)
{
    uint32_t rem=ms%60000u;
    uint32_t mm=ms/60000u;
    uint32_t ss=rem/1000u;
    uint32_t mil=rem%1000u;
    if(mm>99u) { mm=99u; }
    b[0]=(char)('0'+mm/10u); b[1]=(char)('0'+mm%10u); b[2]=':';
    b[3]=(char)('0'+ss/10u); b[4]=(char)('0'+ss%10u); b[5]='.';
    b[6]=(char)('0'+mil/100u); b[7]=(char)('0'+(mil/10u)%10u); b[8]=(char)('0'+mil%10u); b[9]=0;
}
/* 分圈用时: <60s -> "SS.hh"; 60s..99:59 -> "M:SS.hh"; >=100min -> "MM:SS.hh" */
static void Sw_FmtLap(char *b,uint32_t ms)
{
    uint32_t mm=ms/60000u, rem=ms%60000u, ss=rem/1000u, cs=(rem%1000u)/10u;
    if(mm>99u) { mm=99u; }
    if(mm==0u) {
        b[0]=(char)('0'+ss/10u); b[1]=(char)('0'+ss%10u); b[2]='.';
        b[3]=(char)('0'+cs/10u); b[4]=(char)('0'+cs%10u); b[5]=0;
    } else if(mm<10u) {
        b[0]=(char)('0'+mm); b[1]=':';
        b[2]=(char)('0'+ss/10u); b[3]=(char)('0'+ss%10u); b[4]='.';
        b[5]=(char)('0'+cs/10u); b[6]=(char)('0'+cs%10u); b[7]=0;
    } else {
        b[0]=(char)('0'+mm/10u); b[1]=(char)('0'+mm%10u); b[2]=':';
        b[3]=(char)('0'+ss/10u); b[4]=(char)('0'+ss%10u); b[5]='.';
        b[6]=(char)('0'+cs/10u); b[7]=(char)('0'+cs%10u); b[8]=0;
    }
}
/* ---- 大钟盘 ------------------------------------------------------------- */
/* Q8 polar helper: centre and radius are Q8 (pixel<<8), the result is Q8. */
/* 圆心 = 像素栅格中心线 (32.0,32.0): 恰好是 64x64 区域的正中心,
 * 上下、左右都严格对称 —— 大钟盘才能「贴着上下边」又不变形 */
static const int32_t SW_CXQ=SW_CX*256, SW_CYQ=SW_CY*256;
static void Sw_PolarQ8(int32_t rq,uint16_t a,int32_t *xp,int32_t *yp)
{
    *xp=SW_CXQ+((rq*Sin14(a))>>14);
    *yp=SW_CYQ-((rq*Cos14(a))>>14);
}
/* 外环: 120 段 3° 圆弧 ── 用极坐标逐段画, 笔画恰好 1px 落在真圆上,
 * 且与圆心一样严格对称 (OLED_DrawCircle 是整数中点圆, 在 R=32 时
 * 顶部会出现 11px 平顶、底部却在正中裂开 1px, 上下一不对称就很粗糙) */
#define SW_RING_SEG  120
static void Sw_DrawRing(void)
{
    int32_t k,x0,y0,x1,y1;
    for(k=0;k<SW_RING_SEG;k++) {
        Sw_PolarQ8(SW_RING_Q8,(uint16_t)((uint32_t)k*65536u/SW_RING_SEG),&x0,&y0);
        Sw_PolarQ8(SW_RING_Q8,(uint16_t)((uint32_t)(k+1)*65536u/SW_RING_SEG),&x1,&y1);
        OLED_DrawLine(x0>>8,y0>>8,x1>>8,y1>>8,OLED_WHITE);
    }
}
/* 外环 + 60 格刻度: 静态部分, 一帧只画一次, 指针擦除不会碰它 */
static void Sw_DialStatic(void)
{
    int32_t i,x0,y0,x1,y1;
    uint16_t a;
    Sw_DrawRing();
    for(i=0;i<60;i++) {
        int32_t rin=(i%5==0)?SW_MAJ_R:SW_MIN_R;
        a=(uint16_t)((uint32_t)i*65536u/60u);
        Sw_PolarQ8(SW_TICK_R*256,a,&x0,&y0);
        Sw_PolarQ8(rin*256,a,&x1,&y1);
        OLED_DrawLine(x0>>8,y0>>8,x1>>8,y1>>8,OLED_WHITE);
    }
}
/* 盘心: 半径 2 的实心圆点 (5x5, 圆角), 刚好盖住两针在此的交叉 */
static void Sw_Hub(void)
{
    OLED_FillDiscQ8(SW_CXQ,SW_CYQ,384,OLED_WHITE);      /* 半径 1.875px, 圆心同轴 */
}
/* 画针: mode 0 = 总时间针(较长/渐细/短尾), 1 = 分圈针(较短/细/端帽) */
static void Sw_HandDraw(uint16_t a,uint8_t mode)
{
    int32_t x0,y0,x1,y1;
    if(mode==0u) {                                          /* 总时间针: 细 + 渐细针尖 */
        Sw_PolarQ8(-SW_HAND_TAIL*256,a,&x0,&y0);
        Sw_PolarQ8((SW_HAND_R-4)*256,a,&x1,&y1);
        OLED_DrawBrushSegQ8(x0,y0,SW_HAND_W,x1,y1,SW_HAND_W,OLED_WHITE);
        Sw_PolarQ8((SW_HAND_R-4)*256,a,&x0,&y0);
        Sw_PolarQ8(SW_HAND_R*256,a,&x1,&y1);
        OLED_DrawBrushSegQ8(x0,y0,SW_HAND_W,x1,y1,SW_TIP_W,OLED_WHITE);
    } else {                                                /* 分圈针: 更短 + 端帽区分 */
        Sw_PolarQ8(-SW_LAP_TAIL*256,a,&x0,&y0);
        Sw_PolarQ8(SW_LAP_R*256,a,&x1,&y1);
        OLED_DrawLine(x0>>8,y0>>8,x1>>8,y1>>8,OLED_WHITE);
        /* 端帽画成「以针尖为心的圆」: 墨水半径 1.125px < 擦除半径 1.5px,
         * 几何上保证每一帧的墨水都能被同一段擦除完全覆盖 (残影的根因) */
        OLED_FillDiscQ8(x1,y1,SW_CAP_Q8,OLED_WHITE);
    }
}
/* 擦针: 用同一套极坐标 + 稍大的笔宽, 沿线擦净 (不再乱啃刻度/外环) */
static void Sw_HandErase(uint16_t a,uint8_t mode)
{
    int32_t x0,y0,x1,y1;
    if(mode==0u) { Sw_PolarQ8(-SW_HAND_TAIL*256,a,&x0,&y0); Sw_PolarQ8(SW_HAND_R*256,a,&x1,&y1); }
    else { Sw_PolarQ8(-SW_LAP_TAIL*256,a,&x0,&y0); Sw_PolarQ8(SW_LAP_R*256,a,&x1,&y1); }
    OLED_DrawBrushSegQ8(x0,y0,SW_ERASE_Q8,x1,y1,SW_ERASE_Q8,OLED_BLACK);
}
/* ---- 一行分圈记录 ------------------------------------------------------- */
static void Sw_LapRow(int32_t rowY,uint8_t index,uint32_t lapMs,uint8_t blinkDim)
{
    char b[10];
    int32_t my=rowY+4;
    /* 标记: 圆环始终画(行永远对齐), 翻找历史时圈号数字 400ms 闪烁 */
    if(index<=9u) {
        OLED_DrawCircle(SW_MARK_X0+4,my,SW_MARK_R1,OLED_WHITE);
        if(!blinkDim) { Sw_Glyph5(SW_MARK_X0+3,my-2,index); }
    } else {
        OLED_DrawRoundRect(SW_MARK_X0,rowY,SW_MARK_X0+SW_MARK_CAPW-1,rowY+SW_MARK_CAPH-2,4,OLED_WHITE);
        if(!blinkDim) {
            Sw_Glyph5(SW_MARK_X0+2,my-2,(uint8_t)(index/10u));
            Sw_Glyph5(SW_MARK_X0+7,my-2,(uint8_t)(index%10u));
        }
    }
    Sw_FmtLap(b,lapMs);
    {   /* 左对齐到圈号右侧 (列整齐), 只有超长用时才右对齐贴边 */
        int32_t w=Sw_W9(b);
        int32_t tx=(127-w<SW_VAL_X0)?(127-w):SW_VAL_X0;
        Sw_Str9(tx,rowY,b);
    }
}
/* 列表区的签名: 圈数/游标/闪烁相位/每行数值 任一变化就整块重画 */
static uint32_t Sw_ListSig(const SwLapT *laps,uint16_t lapCount,uint16_t lapHead,uint16_t lapView,uint8_t blinkOn)
{
    uint32_t h=(uint32_t)lapCount*131u+(uint32_t)lapView*7u+((uint32_t)blinkOn+1u)*3u;
    uint16_t row;
    for(row=0u;row<SW_ROW_N;row++) {
        uint16_t logical=(uint16_t)(lapView+row);
        uint32_t idx;
        if(logical>=lapCount) { break; }
        idx=((uint32_t)lapHead+SW_LAP_MAX-(uint32_t)logical)%SW_LAP_MAX;
        h=h*33u+(uint32_t)laps[idx].index*3u+(laps[idx].lapMs&0x7FFFu);
    }
    return h?h:1u;
}
#define SW_LIST_X0 65
static void Sw_DrawList(const SwLapT *laps,uint16_t lapCount,uint16_t lapHead,uint16_t lapView,uint8_t blinkOn)
{
    int32_t row;
    OLED_FillRect(SW_LIST_X0,SW_ROW_Y0-2,128-SW_LIST_X0,SW_ROW_N*SW_ROW_PITCH+2,OLED_BLACK);
    for(row=0;row<SW_ROW_N;row++) {
        uint16_t logical=(uint16_t)(lapView+(uint16_t)row);
        uint32_t idx;
        if(logical>=lapCount) { break; }
        idx=((uint32_t)lapHead+SW_LAP_MAX-(uint32_t)logical)%SW_LAP_MAX;
        Sw_LapRow(SW_ROW_Y0+row*SW_ROW_PITCH,(uint8_t)(laps[idx].index>99u?99u:laps[idx].index),
                  laps[idx].lapMs,(uint8_t)((row==0 && lapView>0u && !blinkOn)?1u:0u));
    }
}
/* ---- 对外接口 ----------------------------------------------------------- */
static uint8_t  s_swValid=0u;
static uint32_t s_swPrevMs=0u;
static char     s_swPrevText[12]={0};
static uint16_t s_swPrevHandA=0xFFFFu;
static uint16_t s_swPrevLapA=0xFFFFu;
static uint32_t s_swPrevListSig=0xFFFFFFFFu;
void Scene_StopwatchReset(void)
{
    s_swValid=0u; s_swPrevText[0]=0; s_swPrevHandA=0xFFFFu; s_swPrevLapA=0xFFFFu;
    s_swPrevListSig=0xFFFFFFFFu;
}
/* 分圈针的角度: 从「上一次分圈」到现在的进度, 0 秒 = 12 点方向正上 → 每 60 秒一圈 */
static uint16_t Sw_LapAngle(uint32_t swMs,const SwLapT *laps,uint16_t lapCount,uint16_t lapHead)
{
    uint32_t lapStart=lapCount?laps[lapHead].totalMs:0u;
    uint32_t lapMs=(swMs>lapStart)?(swMs-lapStart):0u;
    return (uint16_t)(((lapMs%60000u)*65536u)/60000u);
}
void Scene_Stopwatch(uint32_t tMs,uint32_t swMs,const SwLapT *laps,uint16_t lapCount,
                     uint16_t lapHead,uint16_t lapView,uint8_t running)
{
    char b[12];
    uint16_t totalA=(uint16_t)(((swMs%60000u)*65536u)/60000u);
    uint16_t lapA=Sw_LapAngle(swMs,laps,lapCount,lapHead);
    uint8_t blinkOn=(uint8_t)(((tMs/SW_BLINK_MS)&1u)==0u);
    uint32_t sig;
    (void)running;
    if(!s_swValid) {                                   /* 首帧: 整屏重画 */
        OLED_Clear();
        Sw_DialStatic();
        Sw_HandDraw(lapA,1u);
        Sw_HandDraw(totalA,0u);
        Sw_Hub();
        Sw_FmtTotal(b,swMs);
        Sw_Str9(SW_TIMER_X,SW_TIMER_Y,b);
        Sw_DrawList(laps,lapCount,lapHead,lapView,blinkOn);
        {
            uint8_t i;
            for(i=0u;i<12u;i++) { s_swPrevText[i]=b[i]; if(!b[i]) { break; } }
        }
        s_swPrevMs=swMs; s_swPrevHandA=totalA; s_swPrevLapA=lapA;
        s_swPrevListSig=Sw_ListSig(laps,lapCount,lapHead,lapView,blinkOn);
        s_swValid=1u;
        return;
    }
    /* 两根针: 只擦旧的、画新的 (分圈针每帧都在扫, 所以排在总时间针下面) */
    if(totalA!=s_swPrevHandA || lapA!=s_swPrevLapA) {
        Sw_HandErase(s_swPrevLapA,1u);
        Sw_HandErase(s_swPrevHandA,0u);
        Sw_HandDraw(lapA,1u);
        Sw_HandDraw(totalA,0u);
        Sw_Hub();
        s_swPrevHandA=totalA; s_swPrevLapA=lapA;
    }
    /* 计时器文字: 只动变化的字符格 */
    if(swMs!=s_swPrevMs) {
        uint8_t i;
        Sw_FmtTotal(b,swMs);
        Sw_TextDiff9(SW_TIMER_X,SW_TIMER_Y,s_swPrevText,b);
        for(i=0u;i<12u;i++) { s_swPrevText[i]=b[i]; if(!b[i]) { break; } }
        s_swPrevMs=swMs;
    }
    /* 分圈列表: 内容/游标/闪烁相位变化时整块重画 */
    sig=Sw_ListSig(laps,lapCount,lapHead,lapView,blinkOn);
    if(sig!=s_swPrevListSig) {
        Sw_DrawList(laps,lapCount,lapHead,lapView,blinkOn);
        s_swPrevListSig=sig;
    }
}
#if defined(FW_SIMULATOR)
/* Simulator-only: format into a static buffer and hand the string to the test. */
static char s_swFmtBuf[16];
__attribute__((export_name("sim_sw_fmt"))) uint32_t Sim_SwFmt(uint32_t ms)
{
    Sw_FmtTotal(s_swFmtBuf,ms);
    return (uint32_t)(uintptr_t)s_swFmtBuf;
}
__attribute__((export_name("sim_sw_lapfmt"))) uint32_t Sim_SwLapFmt(uint32_t ms)
{
    Sw_FmtLap(s_swFmtBuf,ms);
    return (uint32_t)(uintptr_t)s_swFmtBuf;
}
#endif
void Scene_Compose(uint8_t a[8][128],uint8_t b[8][128],uint16_t p)
{
    int32_t x,y,dx,dy,d2,R,fn,fo,sx,sy,bit,idx,m;
    if(p>256u) { p=256u; } R=((int32_t)p*80)>>8; fn=1024-3*(int32_t)p; fo=256-((3*(int32_t)p)>>2);
    for(y=0;y<64;y++) { for(x=0;x<128;x++) {
        dx=x-64; dy=y-32; d2=dx*dx+dy*dy;
        if(d2<R*R) { sx=64+((dx*fn)>>8); sy=32+((dy*fn)>>8); } else { sx=64+((dx*fo)>>8); sy=32+((dy*fo)>>8); }
        if(sx<0 || sx>=128 || sy<0 || sy>=64) { bit=0; } else if(d2<R*R) { bit=(b[sy>>3][sx]>>(sy&7))&1; } else { bit=(a[sy>>3][sx]>>(sy&7))&1; }
        if(R>=2 && d2>=(R-1)*(R-1) && d2<(R+1)*(R+1)) { bit=1; } idx=y>>3; m=1<<(y&7);
        if(bit) { OLED_GRAM[idx][x] |= (uint8_t)m; } else { OLED_GRAM[idx][x] &= (uint8_t)~m; }
    } }
}
#if 0 /* V16: legacy RLE decoder retired */
static void Cat_Draw(uint32_t tMs)
{
    uint32_t frame=(tMs/CAT_FRAME_MS)%CAT_FRAME_COUNT,r=s_catOffsets[frame],end=s_catOffsets[frame+1u];
    uint16_t pos=0u,k;
    uint8_t count,mask,ink,eyeOpen,p,x;
    int32_t ex,ey;
    while(r+3u<=end && pos<CAT_FRAME_BYTES) {
        count=s_catData[r++]; mask=s_catData[r++]; ink=s_catData[r++];
        if(!count || pos+(uint16_t)count>CAT_FRAME_BYTES) { return; }
        for(k=0u;k<count;k++,pos++) {
            p=(uint8_t)(pos>>6); x=(uint8_t)(CAT_DRAW_X+(pos&63u));
            OLED_GRAM[p][x]=(uint8_t)((OLED_GRAM[p][x] & (uint8_t)~mask) | (ink & mask));
        }
    }
    eyeOpen=s_catBlink[(tMs/CAT_FRAME_MS)%96u];
    if(eyeOpen<6u) { for(k=0u;k<4u;k+=2u) {
        ex=CAT_DRAW_X+s_catEyes[frame*4u+k]; ey=s_catEyes[frame*4u+k+1u];
        OLED_FillRect(ex-1,ey-3,2,6,OLED_WHITE); OLED_FillRect(ex-1,ey-(int32_t)(eyeOpen/2u),2,eyeOpen,OLED_BLACK);
    } }
}
#endif
#define FW_ROCKETS 4u
#define FW_SPARKS 160u
#define FW_G (40*256)
#define FW_SG (18*256)
typedef struct { int32_t x,y,vx,vy,drift,wamp; uint16_t wob; uint8_t alive; int16_t tx[2],ty[2]; } Rocket;
typedef struct { int32_t x,y; int16_t vx,vy,life; uint8_t alive; } Spark;
static Rocket s_rk[FW_ROCKETS];
static Spark s_sp[FW_SPARKS];
static uint32_t s_rng=0x2545F491u,s_lastT=0u,s_nextSpawn=60u,s_fwClock=0u;
static uint8_t s_side=0u,s_drawn=0u;
static const uint8_t s_starXY[10][2]={{4,6},{18,14},{30,3},{110,4},{122,18},{100,9},{8,40},{120,40},{14,52},{116,56}};
static uint32_t Rnd(void) { s_rng^=s_rng<<13; s_rng^=s_rng>>17; s_rng^=s_rng<<5; return s_rng; }
static uint32_t RndN(uint32_t n) { return Rnd()%n; }
static void Fw_Burst(int32_t px,int32_t py)
{
    uint32_t n,i,base;
    uint16_t k=0u;
    int32_t spd,sp,ang;
    uint8_t ring;
    n=26u+RndN(15u); base=Rnd()&65535u; spd=22+(int32_t)RndN(40u); ring=(uint8_t)(RndN(3u)==0u);
    for(i=0u;i<n;i++) {
        while(k<FW_SPARKS && s_sp[k].alive) { k++; } if(k>=FW_SPARKS) { break; }
        ang=(int32_t)((base+i*65536u/n)&65535u)+(int32_t)RndN(2400u)-1200; ang &= 65535;
        sp=ring?spd:spd*(int32_t)(40u+RndN(61u))/100;
        s_sp[k].x=px*256+128; s_sp[k].y=py*256+128;
        s_sp[k].vx=(int16_t)(Sin14((uint16_t)ang)*sp/64); s_sp[k].vy=(int16_t)(-Cos14((uint16_t)ang)*sp/64);
        s_sp[k].life=(int16_t)(700+(int32_t)RndN(650u)); s_sp[k].alive=1u;
    }
}
static void Fw_Spawn(void)
{
    uint16_t i;
    int32_t x;
    for(i=0u;i<FW_ROCKETS;i++) { if(!s_rk[i].alive) { break; } } if(i>=FW_ROCKETS) { return; }
    s_side^=1u; x=s_side?8+(int32_t)RndN(28u):92+(int32_t)RndN(28u);
    s_rk[i].x=x*256; s_rk[i].y=64*256; s_rk[i].vx=0; s_rk[i].vy=-(int32_t)(55u+RndN(14u))*256;
    s_rk[i].drift=((int32_t)RndN(25u)-12)*256; s_rk[i].wamp=(int32_t)(12u+RndN(22u))*256; s_rk[i].wob=(uint16_t)Rnd();
    s_rk[i].tx[0]=s_rk[i].tx[1]=(int16_t)x; s_rk[i].ty[0]=s_rk[i].ty[1]=64; s_rk[i].alive=1u;
}
static void Fw_Step(int32_t dt)
{
    uint16_t i;
    for(i=0u;i<FW_ROCKETS;i++) {
        Rocket *r=&s_rk[i];
        int32_t hx,hy;
        if(!r->alive) { continue; }
        r->wob=(uint16_t)(r->wob+(uint32_t)(dt*94)); r->vx=r->drift+Sin14(r->wob)*r->wamp/16384;
        r->vy+=FW_G*dt/1000; r->x+=r->vx*dt/1000; r->y+=r->vy*dt/1000; hx=r->x>>8; hy=r->y>>8;
        r->tx[1]=r->tx[0]; r->ty[1]=r->ty[0]; r->tx[0]=(int16_t)hx; r->ty[0]=(int16_t)hy;
        if(r->vy>=0 || hy<6) { if(hx>=0 && hx<128 && hy>=0 && hy<64) { Fw_Burst(hx,hy); } r->alive=0u; }
        else if(hx < -4 || hx>131) { r->alive=0u; }
    }
    for(i=0u;i<FW_SPARKS;i++) {
        Spark *s=&s_sp[i];
        if(!s->alive) { continue; } s->life=(int16_t)(s->life-dt); if(s->life<=0) { s->alive=0u; continue; }
        s->vx=(int16_t)(s->vx-s->vx*dt/800); s->vy=(int16_t)(s->vy+FW_SG*dt/1000-s->vy*dt/800);
        s->x+=(int32_t)s->vx*dt/1000; s->y+=(int32_t)s->vy*dt/1000;
    }
}
static void Fw_Draw(void)
{
    uint16_t i;
    int32_t px,py,tx,ty,spd;
    for(i=0u;i<FW_ROCKETS;i++) { if(s_rk[i].alive) { OLED_DrawLine(s_rk[i].tx[1],s_rk[i].ty[1],s_rk[i].tx[0],s_rk[i].ty[0],OLED_WHITE); } }
    for(i=0u;i<FW_SPARKS;i++) {
        Spark *s=&s_sp[i];
        if(!s->alive || (s->life<260 && ((s->life/80)&1))) { continue; }
        px=s->x>>8; py=s->y>>8; OLED_DrawPixel(px,py,OLED_WHITE);
        spd=((s->vx<0)?-s->vx:s->vx)+((s->vy<0)?-s->vy:s->vy);
        if(spd>30*256) { tx=(s->x-(int32_t)s->vx/25)>>8; ty=(s->y-(int32_t)s->vy/25)>>8; OLED_DrawLine(px,py,tx,ty,OLED_WHITE); }
    }
}
void Scene_AlarmBegin(uint32_t nowMs)
{
    uint16_t i;
    for(i=0u;i<FW_ROCKETS;i++) { s_rk[i].alive=0u; } for(i=0u;i<FW_SPARKS;i++) { s_sp[i].alive=0u; }
    s_rng=0x2545F491u^nowMs; if(!s_rng) { s_rng=1u; }
    s_lastT=nowMs; s_nextSpawn=60u; s_side=0u; s_fwClock=0u; s_drawn=0u;
    CatAnim_Reset(nowMs);
}
/* Frame cadence is owned by the cat player (33/33/34 ms = 30 fps). Fireworks
 * integrate the real elapsed time, so both stay smooth and in step. Each frame
 * is drawn into GRAM: fireworks first, transparent cat foreground second, then
 * one display update. */
uint8_t Scene_Alarm(uint32_t nowMs)
{
    uint32_t tmp;
    uint16_t i;
    int32_t dt=0,px;
    if(s_drawn) {
        if(!CatAnim_Tick(nowMs)) { return 0u; }
        dt=(int32_t)(nowMs-s_lastT); if(dt<0) { dt=0; } if(dt>100) { dt=100; }
        s_lastT=nowMs; s_fwClock+=(uint32_t)dt;
    } else { s_drawn=1u; s_lastT=nowMs; CatAnim_Reset(nowMs); }
    if((int32_t)(s_fwClock-s_nextSpawn)>=0) { Fw_Spawn(); s_nextSpawn=s_fwClock+220u+RndN(360u); }
    Fw_Step(dt); OLED_Clear();
    for(i=0u;i<10u;i++) { tmp=s_fwClock/260u+(uint32_t)i*3u; if((tmp&3u)!=0u) { OLED_DrawPixel(s_starXY[i][0],s_starXY[i][1],OLED_WHITE); } }
    for(px=0;px<128;px+=2) { if(((px+(int32_t)(s_fwClock/50u))&15)<7) { OLED_DrawPixel(px,61,OLED_WHITE); } }
    Fw_Draw(); CatAnim_Draw(); return 1u;
}

/* ===========================================================================
 * V18 settings screen  (设置界面)
 * ---------------------------------------------------------------------------
 * Behaviour required by the specification:
 *   - the screen shows EXACTLY two icons and no text at all (no Chinese,
 *     no English, nothing else);
 *   - 铃声 / 倒计时 (bell) is on the LEFT, 秒表 (stopwatch) is on the RIGHT;
 *   - each icon is enclosed by a continuous, unbroken, thin rounded square
 *     ("钝角的正方形" = obtuse/rounded corners, 1 pixel wide);
 *   - the square of the SELECTED icon blinks, the icon itself never blinks.
 * main.c owns selection and key handling; this block only draws.
 *
 * Geometry is symmetric about the square centre by construction: every row is
 * emitted as a mirrored pair around lx = 23.5 of a 48 pixel box, so the two
 * icons are pixel-symmetric and can never drift.
 * =========================================================================== */
#define MENU_BOX      48u      /* square side in pixels                      */
#define MENU_BOX_Y     8       /* top edge of both squares                   */
#define MENU_BOX_LX   11       /* left  square spans x = 11..58              */
#define MENU_BOX_RX   69       /* right square spans x = 69..116             */
#define MENU_RADIUS   10       /* obtuse corner radius                       */
#define MENU_BLINK_MS 400u     /* selected border blink half period (0.8 s)   */

/* ---- symmetric primitives (local coordinates: lx 0..47, ly 0..47) -------- */
static void Menu_LocalPix(int32_t x0,int32_t ly,int32_t lx,uint8_t c)
{
    OLED_DrawPixel(x0+lx,MENU_BOX_Y+ly,c);
}
/* One row, mirrored: hw = half width in pixels, centred on lx 23.5 */
static void Menu_RowPair(int32_t x0,int32_t ly,int32_t hw,uint8_t c)
{
    int32_t lx;
    if(hw<=0 || ly<0 || ly>=(int32_t)MENU_BOX) { return; }
    if(hw>24) { hw=24; }
    for(lx=24-hw;lx<=23;lx++) {
        Menu_LocalPix(x0,ly,lx,c);
        Menu_LocalPix(x0,ly,47-lx,c);
    }
}
/* Solid disc, mirrored */
static void Menu_Disc(int32_t x0,int32_t ly,int32_t r,uint8_t c)
{
    int32_t dy,hw;
    for(dy=-r;dy<=r;dy++) { hw=(int32_t)OLED_Isqrt((uint32_t)(r*r-dy*dy)); Menu_RowPair(x0,ly+dy,hw+1,c); }
}
/* Thin arc, mirrored, angles in degrees (0 = 3 o'clock, y grows downwards) */
static void Menu_ArcPair(int32_t x0,int32_t lx,int32_t ly,int32_t r,int32_t a0,int32_t a1,uint8_t c)
{
    int32_t a;
    for(a=a0;a<=a1;a+=1) {
        uint16_t q=(uint16_t)((uint32_t)((a%360+360)%360)*65536u/360u);
        int32_t dx=(r*Cos14(q))/16384;
        int32_t dy=-(r*Sin14(q))/16384;
        Menu_LocalPix(x0,ly+dy,lx+dx,c);
        Menu_LocalPix(x0,ly+dy,47-(lx+dx),c);
    }
}
static void Menu_PixRange(int32_t x0,int32_t ly,int32_t lx0,int32_t lx1,uint8_t c)
{
    int32_t lx;
    for(lx=lx0;lx<=lx1;lx++) { Menu_LocalPix(x0,ly,lx,c); }
}

/* ---- 铃声 (bell) --------------------------------------------------------- */
/* Dome profile: half width per row, from the crown down to the rim.
 * The first rows round the shoulder off, then the sides open up almost
 * vertically - that silhouette is what reads as a bell (the reference photo's
 * bell is a filled dome with a wide rim, a clapper and ring waves). */
static const uint8_t s_bellHW[22]={
    2u,4u,5u,6u,7u,8u,8u,9u,9u,9u,9u,10u,10u,10u,10u,11u,11u,11u,11u,12u,12u,11u
};
/* Menu_ArcPair draws a mirrored pair of arcs; drawing the same radius twice
 * fills the +-1 degree neighbour, which is what makes the wave 2 px thick and
 * continuous instead of a dotted 1 px line. */
static void Menu_Bell(int32_t x0,int32_t lyc)
{
    int32_t r;
    /* ring waves: two radii per side. Where an arc runs behind the bell body it
     * is covered by the (white) body, so the visible parts are exactly the four
     * waves of the reference picture. */
    for(r=15;r<=16;r++) { Menu_ArcPair(x0,24,lyc,r,30,66,OLED_WHITE); }        /* upper wave  */
    for(r=18;r<=19;r++) { Menu_ArcPair(x0,24,lyc,r,34,68,OLED_WHITE); }        /* upper, outer */
    for(r=16;r<=17;r++) { Menu_ArcPair(x0,24,lyc,r,-64,-22,OLED_WHITE); }      /* lower wave  */
    for(r=19;r<=20;r++) { Menu_ArcPair(x0,24,lyc,r,-60,-24,OLED_WHITE); }      /* lower, outer */
    /* crown stem + dome + rim */
    Menu_RowPair(x0,lyc-18,2,OLED_WHITE);
    Menu_RowPair(x0,lyc-17,3,OLED_WHITE);
    for(r=0;r<22;r++) { Menu_RowPair(x0,lyc-16+r,(int32_t)s_bellHW[r],OLED_WHITE); }
    /* clapper, separated from the rim by a dark gap */
    Menu_RowPair(x0,lyc+8,5,OLED_WHITE);
    Menu_RowPair(x0,lyc+9,5,OLED_WHITE);
    Menu_RowPair(x0,lyc+10,4,OLED_WHITE);
    Menu_RowPair(x0,lyc+11,2,OLED_WHITE);
}

/* ---- 秒表 (stopwatch) ---------------------------------------------------- */
static void Menu_Stopwatch(int32_t x0,int32_t lyc)
{
    /* NOTE: Menu_* helpers take LOCAL cell coordinates, while OLED_* primitives
     * take SCREEN coordinates. Mixing the two shifted the dial by MENU_BOX_Y -
     * every coordinate below is converted once, at the top. */
    int32_t sx=x0+23, sy=MENU_BOX_Y+lyc;
    int32_t cq=sx*256+128, dq=sy*256+128;
    /* The reference picture is an orange dial with a white ring; inverted for a
     * 1-bit OLED that is a 2 px white ring on a dark face. */
    OLED_DrawCircle(sx,sy,15,OLED_WHITE);
    OLED_DrawCircle(sx,sy,14,OLED_WHITE);              /* 2 px bezel */
    Menu_Disc(x0,lyc,13,OLED_BLACK);                   /* dark face  */
    Menu_PixRange(x0,lyc-12,23,25,OLED_WHITE);         /* 12 o'clock marker */
    Menu_PixRange(x0,lyc-11,23,25,OLED_WHITE);
    Menu_PixRange(x0,lyc-10,23,25,OLED_WHITE);
    Menu_PixRange(x0,lyc-9,23,25,OLED_WHITE);
    Menu_PixRange(x0,lyc-8,23,25,OLED_WHITE);
    /* hand towards 10 o'clock + centre hub */
    OLED_DrawBrushSegQ8(cq,dq,2*256,cq-7*256,dq-9*256,1*256,OLED_WHITE);
    OLED_FillDiscQ8(cq,dq,2*256,OLED_WHITE);
}

/* ---- 设置界面 ------------------------------------------------------------ */
/* icon: 0 = 铃声(bell), 1 = 秒表(stopwatch).  selected: 1 = this cell is the
 * current choice, its border blinks.  The two flags are deliberately separate:
 * an earlier version overloaded one variable and the icons ended up swapped. */
static void Menu_Cell(int32_t x0,uint8_t icon,uint8_t selected,uint8_t blinkOn)
{
    int32_t x1=x0+(int32_t)MENU_BOX-1;
    int32_t y1=MENU_BOX_Y+(int32_t)MENU_BOX-1;
    if(!selected || blinkOn) { OLED_DrawRoundRect(x0,MENU_BOX_Y,x1,y1,MENU_RADIUS,OLED_WHITE); }
    if(icon==0u) { Menu_Bell(x0,24); } else { Menu_Stopwatch(x0,24); }
}
void Scene_Menu(uint32_t tMs,uint8_t sel)
{
    uint8_t blinkOn=(uint8_t)(((tMs/MENU_BLINK_MS)&1u)==0u);
    OLED_Clear();
    Menu_Cell((int32_t)MENU_BOX_LX,0u,(uint8_t)(sel==0u),blinkOn);
    Menu_Cell((int32_t)MENU_BOX_RX,1u,(uint8_t)(sel!=0u),blinkOn);
}

/* ===========================================================================
 * V23  设置2 (计算器 / 游戏)  +  游戏黑屏占位  +  计算器界面
 * ---------------------------------------------------------------------------
 * 设置2: 与设置1 完全同一套几何 (48x48 钝角细线方框, 400ms 闪烁), 只是换成
 *        计算器(左) / 游戏(右) 两个图标 —— 背景纯黑, 屏幕上没有任何文字.
 * 计算器: 6 行 x 4 列 (行 0 = [AC] + 实时显示行, 行 1..4 = 16 个按键,
 *        行 5 = [清空] + 空格); 每个按键都有一个**直角方框**, 被选中的方框
 *        400ms 闪烁; 显示行实时显示选中的符号/数字, PA4 可以在这一行前后修改.
 * 平滑: 首帧整屏画一次; 之后只重画「选中格子」和「显示行文字」—— 未选中的
 *        方框与字形一直留在屏上, 总线流量极小, 所以翻动画丝滑.
 * =========================================================================== */

/* ---- 48x48 图标: 计算器 (实心白机身 + 挖黑的显示窗与 12 个按键) ----------
 * 局部坐标 lx 0..47 / ly 0..47, 全部左右镜像 (Menu_RowPair), 所以严格对称。
 * 机身   : lx 10..35, ly 6..45 (圆角)
 * 显示窗 : lx 13..32, ly 11..19 (左右各留 3px, 与机身对称)
 * 按键   : 3 列 x 4 行, 每颗 4x4, 列距 8, 行距 6 → 左右边距都是 3px
 * ----------------------------------------------------------------------- */
static void Menu_Calculator(int32_t x0,int32_t lyc)
{
    int32_t k,r,c;
    for(k=0;k<40;k++) {                                  /* 机身: 圆角实心块 */
        int32_t hw=13;
        if(k<3) { hw=(int32_t)(9+k*2); }
        if(k>36) { hw=(int32_t)(9+(39-k)*2); }
        Menu_RowPair(x0,lyc-18+k,hw,OLED_WHITE);
    }
    for(k=0;k<9;k++) { Menu_PixRange(x0,lyc-13+k,13,32,OLED_BLACK); }   /* 显示窗 */
    Menu_PixRange(x0,lyc-11,15,28,OLED_WHITE);                          /* 窗里的数字笔画 */
    Menu_PixRange(x0,lyc-9,15,24,OLED_WHITE);
    for(r=0;r<4;r++) {                                   /* 12 颗按键 */
        for(c=0;c<3;c++) {
            int32_t lx=(int32_t)(13+c*8),ly=lyc-2+r*6,a,b;
            for(a=0;a<4;a++) { for(b=0;b<4;b++) { Menu_LocalPix(x0,ly+a,lx+b,OLED_BLACK); } }
        }
    }
}
/* ---- 48x48 图标: 游戏手柄 (实心白机身 + 挖黑的十字键和 A/B 按键) ---------
 * 机身: lx 6..41, ly 11..36 (26 行高, 与计算器图标视觉分量相当)
 * 十字键: 竖臂 lx 16..18 / ly 16..30, 横臂 lx 12..22 / ly 21..23
 * A/B   : lx 28..32 / ly 18..22 与 lx 34..38 / ly 25..29 (斜排)
 * ----------------------------------------------------------------------- */
static void Menu_Game(int32_t x0,int32_t lyc)
{
    int32_t k,r;
    for(k=0;k<26;k++) {                                  /* 手柄机身 */
        int32_t hw=18;
        if(k<3) { hw=(int32_t)(12+k*3); }
        if(k>22) { hw=(int32_t)(12+(25-k)*3); }
        Menu_RowPair(x0,lyc-13+k,hw,OLED_WHITE);
    }
    for(r=0;r<15;r++) { Menu_PixRange(x0,lyc-8+r,16,18,OLED_BLACK); }   /* 十字键: 竖臂 */
    for(r=0;r<3;r++)  { Menu_PixRange(x0,lyc-3+r,12,22,OLED_BLACK); }   /* 十字键: 横臂 */
    for(r=0;r<5;r++)  { Menu_PixRange(x0,lyc-6+r,28,32,OLED_BLACK); }   /* 按键 A */
    for(r=0;r<5;r++)  { Menu_PixRange(x0,lyc+1+r,34,38,OLED_BLACK); }   /* 按键 B */
}
/* icon: 0 = 计算器, 1 = 游戏; selected 的细线钝角方框闪烁 */
static void Menu2_Cell(int32_t x0,uint8_t icon,uint8_t selected,uint8_t blinkOn)
{
    int32_t x1=x0+(int32_t)MENU_BOX-1;
    int32_t y1=MENU_BOX_Y+(int32_t)MENU_BOX-1;
    if(!selected || blinkOn) { OLED_DrawRoundRect(x0,MENU_BOX_Y,x1,y1,MENU_RADIUS,OLED_WHITE); }
    if(icon==0u) { Menu_Calculator(x0,24); } else { Menu_Game(x0,24); }
}
void Scene_Menu2(uint32_t tMs,uint8_t sel)
{
    uint8_t blinkOn=(uint8_t)(((tMs/MENU_BLINK_MS)&1u)==0u);
    OLED_Clear();
    Menu2_Cell((int32_t)MENU_BOX_LX,0u,(uint8_t)(sel==0u),blinkOn);
    Menu2_Cell((int32_t)MENU_BOX_RX,1u,(uint8_t)(sel!=0u),blinkOn);
}

