/* 44x44 位图 blit: 逐位拷贝, MSB = 最左像素 */
static void Glyph44(int32_t x0,int32_t y0,const uint8_t *g)
{
    int32_t y,b,bit;
    for(y=0;y<44;y++) {
        for(b=0;b<6;b++) {
            uint8_t v=g[y*6+b];
            if(!v) { continue; }
            for(bit=0;bit<8;bit++) {
                if(v & (uint8_t)(0x80u>>bit)) { OLED_DrawPixel(x0+b*8+bit,y0+y,OLED_WHITE); }
            }
        }
    }
}
static void Menu3_Cell(int32_t x0,uint8_t icon,uint8_t selected,uint8_t blinkOn)
{
    int32_t x1=x0+(int32_t)MENU_BOX-1;
    int32_t y1=MENU_BOX_Y+(int32_t)MENU_BOX-1;
    if(!selected || blinkOn) { OLED_DrawRoundRect(x0,MENU_BOX_Y,x1,y1,MENU_RADIUS,OLED_WHITE); }
    Glyph44(x0+2,MENU_BOX_Y+2,(icon==0u)?s_gear44:s_mag44);   /* 44 -> (48-44)/2 */
}
void Scene_SetMenu(uint32_t tMs,uint8_t sel)
{
    uint8_t blinkOn=(uint8_t)(((tMs/MENU_BLINK_MS)&1u)==0u);
    OLED_Clear();
    Menu3_Cell((int32_t)MENU_BOX_LX,MENU3_SEL_GEAR,(uint8_t)(sel==MENU3_SEL_GEAR),blinkOn);
    Menu3_Cell((int32_t)MENU_BOX_RX, MENU3_SEL_MAG, (uint8_t)(sel==MENU3_SEL_MAG), blinkOn);
}

/* ===========================================================================
 * V26  日期/时间编辑器  (时间界面 PA7 -> 齿轮 -> PA5)
 * ---------------------------------------------------------------------------
 * 布局 (128x64, 黑底白像素):
 *
 *    x=0        52 54    94 96      128
 *    y=0   ┌─────────┐ ┌─────┐ ┌─────┐       年 / 月 / 日  三个"日历外围"
 *          │ 〇    〇 │ │〇  〇│ │〇  〇│       构造照参考照片: 实心圆角本体
 *          │ ┌─────┐ │ │┌───┐│ │┌───┐│       + 厚边框 + 内窗口 + 顶部两个
 *          │ │2026 │ │ ││ 10││ ││ 17││       装订环(环与本体之间留黑缝)
 *          │ └─────┘ │ │└───┘│ │└───┘│
 *    y=34  └─────────┘ └─────┘ └─────┘
 *    y=36  ┌─────┐ ┌─────┐ ┌─────┐ ┌─────┐  时 / 分 / 秒 各自一个细线框,
 *          │ 23   │ │ 56   │ │ 58  │ │ WED │   框与框之间用冒号隔开 (V28);
 *    y=62  └─────┘ └─────┘ └─────┘ └─────┘   右边同样是日历外围
 *
 *  分隔用的 2 px 竖缝把年与月、月与日分开, 与照片里"装订环之间的黑缝"同构。
 *
 * 字形: 自带的 5x10 "紧凑"字形 (Panel 字形的半尺寸变体), 所有数字都是连通的
 *       单笔画, 所以 1 px 细线也清晰; 年 4 位 = 4*6-1 = 23 px。
 *
 * 动画: 值变化时按"日历翻页"处理 —— 一条翻折线从一侧扫到另一侧,
 *       旧页被逐步抬起(只在翻折线内侧露出)、新页从另一侧露出来,
 *       折线上有 1px 纸边高光; smoothstep 缓动 220ms, 起收都慢、中间快。
 *       PA5(下一页) = 从底部往上翻, PA6(上一页) = 从顶部往下翻, 互为镜像。
 *       选中的外围 400ms 闪烁。
 * 刷新: 只重画"变化的那一格", 一帧通常几十~两百字节总线流量。
 * 选中: 年/月/日 闪日历外框; 时/分/秒 **各自**闪自己的细线框 (互不影响);
 *       星期永远常亮 (不可选中)。
 * =========================================================================== */
#define DE_ROW1_Y    0
#define DE_ROW1_H    34
#define DE_ROW2_Y    36
#define DE_ROW2_H    27
/* 翻页动画时长: 220ms ≈ 13 帧 @60fps, 够看清翻折线的行走, 又不拖沓 */
#define DE_FLIP_MS   220u


/* 三个日期格: x / 宽  ->  46 + 3 + 38 + 3 + 38 = 128 (正好铺满) */
static const uint8_t s_deX[3]={0u,49u,90u};
static const uint8_t s_deW[3]={46u,38u,38u};

/* ---- 5x10 紧凑字形 -------------------------------------------------------
 * 复用 Panel 的路径数据, 用半坐标映射到 5x10: x' = x/4, y' = y/4.
 * 笔画半径 0 -> 精确 1 px, 数字仍然首尾相接。 */
static void De_GlyphSmall(int32_t ox,int32_t oy,uint8_t d)
{
    const PanelGlyph *g;
    uint8_t pi,k;
    if(d>9u) { return; }
    g=&s_pnGlyph[d];
    for(pi=0u;pi<g->n;pi++) {
        const PanelPath *p=&g->paths[pi];
        for(k=0u;k+1u<p->n;k++) {
            int32_t x0=ox*256+((int32_t)p->p[k].x*64);      /* /4 in Q8 = *64  */
            int32_t y0=oy*256+((int32_t)p->p[k].y*64);
            int32_t x1=ox*256+((int32_t)p->p[k+1].x*64);
            int32_t y1=oy*256+((int32_t)p->p[k+1].y*64);
            OLED_DrawBrushSegQ8(x0,y0,0,x1,y1,0,OLED_WHITE);
        }
    }
}
/* 紧凑数字串: 每位 6 px (5 宽 + 1 间距), 高 10 px */
static void De_Num(int32_t x,int32_t y,uint16_t v,uint8_t n,int32_t dy)
{
    uint8_t i,k;
    uint16_t p10=1u,dd;
    for(k=1u;k<n;k++) { p10=(uint16_t)(p10*10u); }
    for(i=0u;i<n;i++) {
        dd=(uint16_t)((v/p10)%10u);
        De_GlyphSmall(x+(int32_t)i*6,y+dy,(uint8_t)dd);
        if(p10>=10u) { p10=(uint16_t)(p10/10u); } else { p10=1u; }
    }
}
static int32_t De_NumW(uint8_t n) { return (int32_t)n*6-1; }

/* ---- 日历外围 (构造 = 参考照片) -----------------------------------------
 * 照片实测比例 (本体 344x316 px):
 *   边框  25/344 = 7.3 %      顶部带 80/344 = 23.3 %     装订环宽 26/344 = 7.6 %
 * 全部用逐像素画法, 不依赖圆角矩形原语在极小尺寸下的行为 —— 这个格子最小
 * 只有 32x34, 通用原语在这里很容易退化成一条线。 */
static void De_Pix(int32_t x,int32_t y,uint8_t c)
{
    if(x<0 || y<0 || x>=128 || y>=64) { return; }
    OLED_DrawPixel(x,y,c);
}
/* 钝角方框覆盖判定: 中间十字带直接算内部, 只有四个 r x r 的角需要判圆。 */
static uint8_t De_InRound(int32_t dx,int32_t dy,int32_t w,int32_t h,int32_t r)
{
    int32_t ax,ay,cx,cy;
    if(dx<0 || dy<0 || dx>=w || dy>=h) { return 0u; }
    if(dx>=r && dx<w-r) { return 1u; }              /* 竖直中带 */
    if(dy>=r && dy<h-r) { return 1u; }              /* 水平中带 */
    /* 到这里说明 (dx,dy) 落在某个 r x r 的角区里; 角心是 (r,r) 等 */
    cx=(dx<r)?r:(w-1-r);
    cy=(dy<r)?r:(h-1-r);
    ax=dx-cx; if(ax<0) { ax=-ax; }
    ay=dy-cy; if(ay<0) { ay=-ay; }
    return (uint8_t)((ax*ax+ay*ay)<=(r*r));
}
/* 一个日历外围。borderOn=0 时只把边框画黑, 本体/内窗/数字原样保留 ——
 * "选中的框闪烁" 就只是框线明暗, 内容一直可读 (与设置1/2 图标不闪是同一规则).
 *
 * 比例全部来自参考照片的实测 (本体 344x316):
 *   边框 25/344 = 7.3%    装订环宽 27/344 = 7.8%    环高 75/344 = 21.8%
 *   环向上探出本体 27/344 = 7.8%, 环中心在宽度的 23% 与 69%
 * 顶部带 (本体顶 -> 内窗顶) 取环高 + 1, 保证环和内窗之间有 1 px 黑缝。 */
static void De_CalFrame(int32_t x0,int32_t y0,int32_t w,int32_t h,uint8_t borderOn)
{
    int32_t b,r,band,rw,rh,r1,r2,i,dx,dy;
    b=(w*73+999)/1000;              if(b<2)  { b=2; }
    r=b+1;                                                    /* 钝角 = 边框+1 */
    rw=(w*78+999)/1000;             if(rw<2) { rw=2; }
    rh=(w*180+999)/1000;            if(rh<3) { rh=3; }
    band=rh+1;                                                /* 环 + 1px 黑缝 */
    if(band>h/2) { band=h/2; }
    r1=x0+(w*23)/100 - rw/2;
    r2=x0+(w*69)/100 - rw/2;

    /* 整行绘制: 一行的墨迹是"圆角范围内的一段连续 run", 直接用 HLine 画,
     * 脏区按行自然合并成 1 段/行 —— 若逐像素画, 每个像素都会触发一次脏区
     * 合并, 首帧在真机上要发出 30+ 次 I2C 寻址事务 (实测 79 ms 卡顿)。
     *
     * 每一行必须**黑白都画**: 边框在暗相要被擦成黑, 否则"选中闪烁"只会亮不
     * 会灭 (V27 把逐像素改成 run 时踩过这个坑 —— 只画白线, 暗相什么也没做,
     * 选中的框就一直亮着)。装订环不属于边框, 它的墨迹任何相位都保留。 */
    for(dy=0;dy<h;dy++) {
        int32_t y=y0+dy, runX=-1, runLen=0;
        uint8_t runCol=0u;                       /* 0=无 1=白 2=黑 */
        for(dx=0;dx<=w;dx++) {
            uint8_t col=0u;
            if(dx<w && De_InRound(dx,dy,w,h,r)) {
                if(dx<b || dx>=w-b || dy<b || dy>=h-b) {
                    col=borderOn?1u:2u;          /* 边框: 亮相白 / 暗相黑 */
                } else if(dy<band) {
                    for(i=0;i<2;i++) {
                        int32_t rx=(i==0)?r1:r2;
                        if(x0+dx>=rx && x0+dx<rx+rw) { col=1u; }   /* 环: 恒亮 */
                    }
                }
            }
            if(col!=runCol) {
                if(runCol!=0u) {
                    OLED_DrawHLine(x0+runX,y,runLen,
                                   (runCol==1u)?OLED_WHITE:OLED_BLACK);
                }
                runX=dx; runLen=0; runCol=col;
            }
            if(col!=0u) { runLen++; }
        }
    }
}

/* ---------------- 状态 (自包含在 Scene.c) -------------------------------- */
#define DE_FIELDS 7
static uint8_t  s_deFresh=1u;
static uint8_t  s_deSelB=0xFFu, s_deBlinkB=0xFFu;
static uint16_t s_deVal[DE_FIELDS]={0xFFFFu,0xFFFFu,0xFFFFu,0xFFFFu,0xFFFFu,0xFFFFu,0xFFFFu};
static uint16_t s_deOld[DE_FIELDS]={0u,0u,0u,0u,0u,0u,0u};
static uint8_t  s_deDir[DE_FIELDS]={0u,0u,0u,0u,0u,0u,0u};
static uint8_t  s_deRoll[DE_FIELDS]={0u,0u,0u,0u,0u,0u,0u};
static uint32_t s_deRollMs[DE_FIELDS]={0u,0u,0u,0u,0u,0u,0u};

/* 俄罗斯方块首帧强制全画 (由 main.c 在开局/重开时调用) */
void Scene_TetrisReset(void) { s_gtFirst=1u; s_gtDrawnSig=0xFFFFu; s_gtDrawnOvl=0xFFu; s_gtDrawnCount=0xFFu; }
/* 覆盖层(暂停/倒数)变了, 强制重画那一条区域 */
void Scene_TetrisOvlReset(void) { s_gtDrawnOvl=0xFFu; s_gtDrawnCount=0xFFu; }

void Scene_DateEditorReset(void)
{
    uint8_t i;
    s_deFresh=1u; s_deSelB=0xFFu; s_deBlinkB=0xFFu;
    for(i=0u;i<DE_FIELDS;i++) { s_deRoll[i]=0u; s_deVal[i]=0xFFFFu; }
    /* 丢掉可能残留的整屏请求: 它的唯一消费者是编辑器的首帧。若上一轮编辑器
     * 在首帧前就被长按 PA4 退出, 标志会留到时间/秒表/计算器界面, 让它们
     * 白做一次整屏写, 甚至打乱 V25 修好的脏区时序。 */
    (void)OLED_TakeFullFlush();
}
/* V28: 时/分/秒 三个独立细线框的左边界 (宽 23, 间隔 6) */
static const int16_t s_deTimeX[3]={0,29,58};

/* 每个字段的窗口矩形 + 绘制方式 */
typedef struct { int16_t x,y,w,h; } DeRect;
static DeRect De_Win(uint8_t f)
{
    DeRect r;
    int32_t b;
    if(f<3u) {                                   /* 年 / 月 / 日 */
        b=(s_deW[f]*73+999)/1000; if(b<2) { b=2; }
        r.x=(int16_t)(s_deX[f]+b);
        r.y=(int16_t)(DE_ROW1_Y+((DE_ROW1_H*233+999)/1000));
        r.w=(int16_t)(s_deW[f]-2*b);
        r.h=(int16_t)(DE_ROW1_H-((DE_ROW1_H*233+999)/1000)-b);
    } else if(f<6u) {                            /* 时 / 分 / 秒 */
        /* V28: 时/分/秒 各自一个细线框 (不再共用一个长框)。
         * 三个框 x = 0 / 29 / 58, 宽 23, 间隔 6 (冒号正好落在间隔中央):
         *   0..22 | 23..28(:) | 29..51 | 52..57(:) | 58..80  = 81 px 铺满
         * 窗口取框内 1px 的 21 px 宽, 两数字 11 px 居中 -> 正好在框中心。 */
        r.x=(int16_t)(s_deTimeX[f-3u]+1); r.y=DE_ROW2_Y+6; r.w=21; r.h=15;
    } else {                                     /* 星期 */
        b=(44*73+999)/1000; if(b<2) { b=2; }
        r.x=(int16_t)(84+b); r.y=(int16_t)(DE_ROW2_Y+((DE_ROW2_H*233+999)/1000));
        r.w=(int16_t)(44-2*b); r.h=(int16_t)(DE_ROW2_H-((DE_ROW2_H*233+999)/1000)-b);
    }
    return r;
}
#if defined(FW_SIMULATOR)
uint32_t Sim_DvF[7]={0u}, Sim_DvV[7]={0u}, Sim_DvN=0u;
__attribute__((export_name("sim_dv"))) uint32_t Sim_DvGet(uint32_t i)
{ return (i<7u)?((Sim_DvF[i]&0xFFu)|((Sim_DvV[i]&0xFFFFu)<<8)):Sim_DvN; }
#endif
static void De_DrawValue(uint8_t f,int32_t dy,uint16_t v)
{
    DeRect r=De_Win(f);
#if defined(FW_SIMULATOR)
    if(f<7u) { Sim_DvF[f]++; Sim_DvV[f]=v; }
#endif
    if(f==0u)      { De_Num(r.x+(r.w-De_NumW(4))/2,r.y+(r.h-10)/2,(uint16_t)(v%10000u),4u,dy); }
    else if(f==6u) {
        static const char wk[7][4]={"SUN","MON","TUE","WED","THU","FRI","SAT"};
        OLED_ShowString(r.x+(r.w-17)/2,r.y+(r.h-8)/2+dy,wk[v%7u],OLED_WHITE);
    } else         { De_Num(r.x+(r.w-De_NumW(2))/2,r.y+(r.h-10)/2,(uint16_t)(v%100u),2u,dy); }
}
/* 0..256 的 smoothstep 缓动: 3p^2 - 2p^3, 纯整数。
 * 起手和落点都慢、中段快 —— 纸页翻过去就是这个加速度曲线。 */
static uint32_t De_Ease(uint32_t el)
{
    uint32_t p,p2;
    if(el>=(uint32_t)DE_FLIP_MS) { return 256u; }
    p=(el*256u)/(uint32_t)DE_FLIP_MS;
    p2=(p*p)>>8;
    return (3u*p2)-((2u*p2*p)>>8);
}

/* 重画一格。
 * 翻页模型 (与实物日历一致): 纸页铰接在**翻折线要离开的那条边**上。
 *   dir=1 (PA5, 从底部往上翻): 旧页留在窗口上方, 翻折线由下往上扫; 下半个
 *          窗口先露出新页, 所以新页从底部升起来。
 *   dir=2 (PA6, 从顶部往下翻): 完全镜像, 旧页留在下方, 新页从顶部降下来。
 * 顺序必须是"先整页画新值, 再把旧值裁到剩余部分盖上去" —— 反过来会把新值
 * 的翻折线内侧擦掉。 */
static void De_Repaint(uint8_t f,uint32_t now)
{
    DeRect r=De_Win(f);
    uint16_t cur=s_deVal[f];
    uint32_t el,amt=0u,cut;
    int32_t lift,y0,y1;
    uint8_t running=0u;

    OLED_FillRect(r.x,r.y,r.w,r.h,OLED_BLACK);      /* FillRect 是 (x,y,w,h) */
    if(s_deRoll[f]) {
        el=(uint32_t)(now-s_deRollMs[f]);
        if(el>=(uint32_t)DE_FLIP_MS) { s_deRoll[f]=0u; }
        else { amt=De_Ease(el); running=1u; }
    }
    /* cut = 旧页还剩下多少行: 动画开始 = 整格(旧值全露), 结束 = 0(全翻走)。
     * 一开始写成 cut=h*amt (0 -> h), 翻折线就从**上往下**走了, 与 PA5
     * "从底部往上翻"正好相反 —— M12 的翻折线轨迹测试抓到了它。 */
    cut=running?(((uint32_t)r.h*(256u-amt))>>8):0u;
    if(cut>(uint32_t)r.h) { cut=(uint32_t)r.h; }
    OLED_SetClipRect(r.x,r.y,r.x+r.w-1,r.y+r.h-1);
    /* 新页从"被翻折线盖住的一侧"外面升上来: 翻折开始时整页压在窗口外,
     * 随旧页让出的高度归位。这样在整个 220ms 里都能看到新数字正在进入,
     * 而不是等到最后 40% 才突然出现 (只做裁切时实测就是这样)。 */
    {
        int32_t ndy=0;
        if(running) {
            ndy=(int32_t)(cut/2u);
            if(s_deDir[f]!=1u) { ndy=-ndy; }        /* 上一页: 新页从上方降下 */
        }
        De_DrawValue(f,ndy,cur);
    }
    if(running && amt>0u) {
        /* 旧页**不做位移**。V27 试过"向铰链收缩"的近似(上抬 h/3), 但在
         * 5x10 的小字形上会让新旧两个数字直接叠在一起, 帧看起来是糊的;
         * 只裁切 + 纸边高光就已经读成翻页, 而且任何一帧都清晰可辨。 */
        lift=0;
        if(s_deDir[f]==1u) {
            y0=r.y; y1=r.y+(int32_t)cut-1;         /* 旧页留在上方 */
        } else {
            y0=r.y+r.h-(int32_t)cut; y1=r.y+r.h-1; /* 旧页留在下方 */
        }
        if(cut==0u) {
            /* 旧页完全翻过去了: 只在铰链处留 1px 纸边 */
            if(s_deDir[f]==1u) { OLED_DrawHLine(r.x,r.y,r.w,OLED_WHITE); }
            else               { OLED_DrawHLine(r.x,r.y+r.h-1,r.w,OLED_WHITE); }
        } else {
            OLED_SetClipRect(r.x,y0,r.x+r.w-1,y1);
            De_DrawValue(f,lift,s_deOld[f]);
            OLED_SetClipRect(r.x,r.y,r.x+r.w-1,r.y+r.h-1);
            /* 纸边高光: 画在旧页与新区之间的那条缝上 */
            if(cut<(uint32_t)r.h) {
                int32_t fy=(s_deDir[f]==1u)?(y1+1):(y0-1);
                OLED_DrawHLine(r.x,fy,r.w,OLED_WHITE);
            }
        }
    }
    OLED_SetClipRect(0,0,-1,-1);
}
/* 一个"时分秒"细线框 (i = 0/1/2)。on=0 时只把框线擦黑, 框内数字原样保留 ——
 * 与日历外围的闪烁规则一致: 闪烁只作用在**外框**, 内容一直可读。 */
static void De_DrawTimeBox(uint8_t i,uint8_t on)
{
    int32_t x0;
    if(i>2u) { return; }
    x0=s_deTimeX[i];
    OLED_DrawRoundRect(x0,DE_ROW2_Y,x0+22,DE_ROW2_Y+DE_ROW2_H-1,6,
                       on?OLED_WHITE:OLED_BLACK);
}
/* 两个冒号 (始终常亮, 不参与闪烁): 分别落在两条 6px 间隔的正中 */
static void De_DrawColons(void)
{
    OLED_FillRect(25,DE_ROW2_Y+12,2,2,OLED_WHITE);
    OLED_FillRect(25,DE_ROW2_Y+18,2,2,OLED_WHITE);
    OLED_FillRect(54,DE_ROW2_Y+12,2,2,OLED_WHITE);
    OLED_FillRect(54,DE_ROW2_Y+18,2,2,OLED_WHITE);
}
/* 首帧: 三个框全部画出 + 冒号 */
static void De_DrawBottomFrame(void)
{
    uint8_t i;
    for(i=0u;i<3u;i++) { De_DrawTimeBox(i,1u); }
    De_DrawColons();
}

void Scene_DateEditor(uint32_t tMs,uint16_t y,uint8_t mo,uint8_t d,uint8_t wd,
                      uint8_t hh,uint8_t mi,uint8_t ss,uint8_t sel)
{
    uint16_t v[DE_FIELDS];
    uint8_t blinkOn=(uint8_t)(((tMs/MENU_BLINK_MS)&1u)==0u);
    uint8_t i,f;
    v[0]=y; v[1]=mo; v[2]=d; v[3]=hh; v[4]=mi; v[5]=ss; v[6]=wd;

    if(s_deFresh) {
        s_deFresh=0u; s_deSelB=0xFFu; s_deBlinkB=0xFFu;
        /* 首帧整屏重画: 请求整屏刷新, 并在"这一帧"就让它生效 —— main.c 在
         * 调用本函数**之后**才决定 oledPartial, 所以这里置标志来得及。 */
        OLED_RequestFullFlush();
        OLED_Clear();
        De_DrawBottomFrame();
        for(i=0u;i<3u;i++) { De_CalFrame(s_deX[i],DE_ROW1_Y,s_deW[i],DE_ROW1_H,1u); }
        De_CalFrame(84,DE_ROW2_Y,44,DE_ROW2_H,1u);
        for(i=0u;i<DE_FIELDS;i++) {
            if(v[i]!=s_deVal[i]) { s_deVal[i]=v[i]; s_deRoll[i]=0u; }
            De_Repaint(i,tMs);
        }
        s_deSelB=sel; s_deBlinkB=blinkOn;
        return;
    }
    /* 值变化 -> 启动滚动 */
    for(i=0u;i<DE_FIELDS;i++) {
        if(v[i]!=s_deVal[i]) {
            s_deOld[i]=s_deVal[i];
            s_deDir[i]=(uint8_t)((v[i]>s_deVal[i])?1u:2u);
            /* 年/月/日 跨月回绕时按"前进"处理, 避免从 2099 滑回 2000 的长跳 */
            if(i<3u && (uint16_t)(s_deOld[i]-v[i])>400u) { s_deDir[i]=1u; }
            s_deRoll[i]=1u; s_deRollMs[i]=tMs;
            s_deVal[i]=v[i];
        }
    }
    /* 选中项 / 闪烁相位变化。
     * 注意: De_CalFrame 会重画整个"日历外围", 内窗口必须重新清黑, 所以画完
     * 框之后**所有**数字都要重画 —— 只补选中项的话, 另外几格的数字会被
     * 每 400 ms 一次的闪烁擦掉 (这正是 V26 开发中抓到的真实 bug)。 */
    if(sel!=s_deSelB || blinkOn!=s_deBlinkB) {
        /* 只有**选中**的那一格需要重画 (它的边框要在亮相/暗相之间切换)。
         * 未选中的格子一直是亮相, 完全不用动 —— 早期版本每 400 ms 把 4 个框
         * 和 7 个数字全部重画一遍, 静置时白白烧掉 2 KB/s 以上的总线带宽。 */
        if(sel<3u) { De_CalFrame(s_deX[sel],DE_ROW1_Y,s_deW[sel],DE_ROW1_H,blinkOn); De_Repaint(sel,tMs); }
        else if(sel==6u) { De_CalFrame(84,DE_ROW2_Y,44,DE_ROW2_H,blinkOn); De_Repaint(6u,tMs); }
        else { De_DrawTimeBox((uint8_t)(sel-3u),blinkOn); }
        if(sel!=s_deSelB && s_deSelB!=0xFFu) {
            /* 换了选中项: 把上一格恢复成常亮 */
            if(s_deSelB<3u) { De_CalFrame(s_deX[s_deSelB],DE_ROW1_Y,s_deW[s_deSelB],DE_ROW1_H,1u); De_Repaint(s_deSelB,tMs); }
            else if(s_deSelB==6u) { De_CalFrame(84,DE_ROW2_Y,44,DE_ROW2_H,1u); De_Repaint(6u,tMs); }
            else { De_DrawTimeBox((uint8_t)(s_deSelB-3u),1u); }
        }
        s_deSelB=sel; s_deBlinkB=blinkOn;
    }
    /* 正在滚动的字段 */
    for(f=0u;f<DE_FIELDS;f++) {
        if(!s_deRoll[f]) { continue; }
        De_Repaint(f,tMs);
        if((uint32_t)(tMs-s_deRollMs[f])>=(uint32_t)DE_FLIP_MS) { s_deRoll[f]=0u; De_Repaint(f,tMs+DE_FLIP_MS); }
    }
}




/* =========================== 计算器界面 ================================== */
#define SC_BLINK_MS 400u
#define CALC_COLW   32                  /* 4 列, 每列 32px */
#define CALC_ROWH0  14                  /* 行 0 (AC + 显示行) 高 14px */
#define CALC_ROWH   10                  /* 行 1..5 每行 10px */
#define CALC_TEXT_X0 36                 /* 显示文字起点 */
#define CALC_TEXT_MAXW 88               /* 显示文字最多这么宽 (超出向左卷) */

/* 5x7 数字 (计算器按键用), 每行 5 bit, bit4 = 最左 */
static const uint8_t s_calc7[10][7]={
    {0x0Eu,0x11u,0x11u,0x11u,0x11u,0x11u,0x0Eu},   /* 0 */
    {0x04u,0x0Cu,0x04u,0x04u,0x04u,0x04u,0x0Eu},   /* 1 */
    {0x0Eu,0x11u,0x01u,0x02u,0x04u,0x08u,0x1Fu},   /* 2 */
    {0x0Eu,0x11u,0x01u,0x06u,0x01u,0x11u,0x0Eu},   /* 3 */
    {0x02u,0x06u,0x0Au,0x12u,0x1Fu,0x02u,0x02u},   /* 4 */
    {0x1Fu,0x10u,0x1Eu,0x01u,0x01u,0x11u,0x0Eu},   /* 5 */
    {0x06u,0x08u,0x10u,0x1Eu,0x11u,0x11u,0x0Eu},   /* 6 */
    {0x1Fu,0x01u,0x02u,0x02u,0x04u,0x04u,0x08u},   /* 7 */
    {0x0Eu,0x11u,0x11u,0x0Eu,0x11u,0x11u,0x0Eu},   /* 8 */
    {0x0Eu,0x11u,0x11u,0x0Fu,0x01u,0x02u,0x0Cu}    /* 9 */
};
/* 3x5 字母 (E/r/o 用于 "Error"; A/C 用于 AC 键) */
static const uint8_t s_calcEro[3][5]={{0x7u,0x4u,0x6u,0x4u,0x7u},{0x5u,0x6u,0x4u,0x4u,0x4u},{0x2u,0x5u,0x5u,0x5u,0x2u}};
/* 3x5 字母: A / C (AC 键) */
static const uint8_t s_calcAC[2][5]={{0x2u,0x5u,0x7u,0x5u,0x5u},{0x3u,0x4u,0x4u,0x4u,0x3u}};

static int32_t Calc_RowY(uint8_t r) { return (r==0u)?0:((int32_t)CALC_ROWH0+(int32_t)(r-1u)*(int32_t)CALC_ROWH); }
static int32_t Calc_ColX(uint8_t c) { return (int32_t)c*(int32_t)CALC_COLW; }
static int32_t Calc_BoxY1(uint8_t r) { return Calc_RowY(r)+((r==0u)?11:9); }

static void Calc_DrawDigit7(int32_t x,int32_t y,uint8_t d)
{
    uint8_t rr,b;
    const uint8_t *g=s_calc7[(uint32_t)d%10u];
    for(rr=0u;rr<7u;rr++) { for(b=0u;b<5u;b++) { if(g[rr]&(uint8_t)(16u>>b)) { OLED_DrawPixel(x+(int32_t)b,y+(int32_t)rr,OLED_WHITE); } } }
}
/* 清空键: 小垃圾桶 (盖 + 提手 + 桶身), 9 行高 */
static void Calc_DrawTrash(int32_t cx,int32_t ytop)
{
    OLED_DrawHLine(cx-2,ytop,5,OLED_WHITE);           /* 提手 */
    OLED_DrawHLine(cx-4,ytop+1,9,OLED_WHITE);         /* 盖   */
    OLED_DrawVLine(cx-3,ytop+2,6,OLED_WHITE);         /* 桶身两侧 */
    OLED_DrawVLine(cx+3,ytop+2,6,OLED_WHITE);
    OLED_DrawHLine(cx-2,ytop+8,5,OLED_WHITE);         /* 桶底 */
    OLED_DrawVLine(cx-1,ytop+3,5,OLED_WHITE);         /* 两条竖纹 */
    OLED_DrawVLine(cx+1,ytop+3,5,OLED_WHITE);
}
/* 按键里的符号: 数字 5x7 / 运算符 7x7 矢量 / AC / 清空图标 */
static void Calc_DrawKeyGlyph(int32_t colx,int32_t rowy,uint8_t key)
{
    int32_t cx=colx+CALC_COLW/2,cy=rowy+5;
    if(key<=9u) { Calc_DrawDigit7(colx+14,rowy+2,key); return; }
    switch(key) {
        case CK_DOT:  OLED_FillRect(cx-1,rowy+6,2,2,OLED_WHITE); break;
        case CK_ADD:  OLED_DrawHLine(cx-3,cy,7,OLED_WHITE); OLED_DrawVLine(cx,cy-3,7,OLED_WHITE); break;
        case CK_SUB:  OLED_DrawHLine(cx-3,cy,7,OLED_WHITE); break;
        case CK_MUL:  OLED_DrawLine(cx-3,cy-3,cx+3,cy+3,OLED_WHITE); OLED_DrawLine(cx-3,cy+3,cx+3,cy-3,OLED_WHITE); break;
        case CK_DIV:  OLED_DrawHLine(cx-3,cy,7,OLED_WHITE); OLED_DrawPixel(cx,cy-3,OLED_WHITE); OLED_DrawPixel(cx,cy+3,OLED_WHITE); break;
        case CK_EQ:   OLED_DrawHLine(cx-3,cy-2,7,OLED_WHITE); OLED_DrawHLine(cx-3,cy+2,7,OLED_WHITE); break;
        case CK_AC: {
            uint8_t rr,b;
            for(rr=0u;rr<5u;rr++) {
                for(b=0u;b<3u;b++) {
                    if(s_calcAC[0][rr]&(uint8_t)(4u>>b)) { OLED_DrawPixel(colx+14+(int32_t)b,rowy+4+(int32_t)rr,OLED_WHITE); }
                    if(s_calcAC[1][rr]&(uint8_t)(4u>>b)) { OLED_DrawPixel(colx+18+(int32_t)b,rowy+4+(int32_t)rr,OLED_WHITE); }
                }
            }
            break;
        }
        case CK_CLEAR: Calc_DrawTrash(cx,rowy+1); break;
        default: break;
    }
}
/* 重画一个格子 (先整格擦黑, 再画方框和符号) —— 增量刷新的最小单位 */
static void Calc_DrawCell(uint8_t r,uint8_t c,uint8_t selected,uint8_t blinkOn)
{
    int32_t x0=Calc_ColX(c)+1,y0=Calc_RowY(r)+1;
    int32_t x1=Calc_ColX(c)+(int32_t)CALC_COLW-2,y1=Calc_BoxY1(r);
    uint8_t key=s_calcKeys[r][c];
    OLED_FillRect(x0-1,y0-1,(x1-x0)+3,(y1-y0)+3,OLED_BLACK);
    if(key==CK_NONE) { return; }
    if(!selected || blinkOn) { OLED_DrawRect(x0,y0,(x1-x0)+1,(y1-y0)+1,OLED_WHITE); }
    Calc_DrawKeyGlyph(Calc_ColX(c),Calc_RowY(r),key);
}
/* 显示行: 一个横跨 3 列的大方框 + 实时表达式 (超出就向左卷, 光标 = 下划线) */
static void Calc_DrawGlyph(int32_t x,char ch)
{
    if(ch>='0'&&ch<='9') { Sw_DrawCh9(x,2,ch,1u); return; }
    if(ch=='.') { OLED_FillRect(x,10,2,1,OLED_WHITE); return; }
    if(ch=='+') { OLED_DrawHLine(x,6,5,OLED_WHITE); OLED_DrawVLine(x+2,4,5,OLED_WHITE); return; }
    if(ch=='-') { OLED_DrawHLine(x,6,5,OLED_WHITE); return; }
    if(ch=='*') { OLED_DrawLine(x,4,x+4,8,OLED_WHITE); OLED_DrawLine(x,8,x+4,4,OLED_WHITE); return; }
    if(ch=='/') { OLED_DrawHLine(x,6,5,OLED_WHITE); OLED_DrawPixel(x+2,4,OLED_WHITE); OLED_DrawPixel(x+2,8,OLED_WHITE); return; }
    {   /* E / r / o: 3x5 */
        const uint8_t *g=0;
        uint8_t rr,b;
        if(ch=='E') { g=s_calcEro[0]; }
        else if(ch=='r') { g=s_calcEro[1]; }
        else if(ch=='o') { g=s_calcEro[2]; }
        if(!g) { return; }
        for(rr=0u;rr<5u;rr++) { for(b=0u;b<3u;b++) { if(g[rr]&(uint8_t)(4u>>b)) { OLED_DrawPixel(x+(int32_t)b,4+(int32_t)rr,OLED_WHITE); } } }
    }
}
static int32_t Calc_GlyphW(char ch) { return (ch=='.')?2:((ch=='E'||ch=='r'||ch=='o')?4:Sw_ChW(ch)); }
static void Calc_DrawDisplay(const char *expr,uint8_t cur,uint8_t isResult)
{
    int32_t x,total=0,start=0,i,len=0,xc=CALC_TEXT_X0,x0First=CALC_TEXT_X0;
    char vis[CALC_EXPR_MAX+1];
    while(expr[len] && len<CALC_EXPR_MAX) { total+=Calc_GlyphW(expr[len]); len++; }
    while(start<len && total>CALC_TEXT_MAXW) { total-=Calc_GlyphW(expr[start]); start++; }
    /* 像真正的计算器那样右对齐 (位数越多越往左铺开, 一眼看清个位在哪) */
    x=CALC_TEXT_X0+((int32_t)CALC_TEXT_MAXW-total);
    if(x<CALC_TEXT_X0) { x=CALC_TEXT_X0; }
    x0First=x; xc=x;
    for(i=0;i<len-start;i++) { vis[i]=expr[start+i]; }
    vis[len-start]=0;
    /* 清显示区内部(留 1px 不碰方框)再画框, 这样增量刷新也不会有残影 */
    OLED_FillRect(CALC_TEXT_X0-3,2,(int32_t)CALC_TEXT_MAXW+6,10,OLED_BLACK);
    OLED_DrawRect(CALC_TEXT_X0-3,1,(int32_t)CALC_TEXT_MAXW+6,11,OLED_WHITE);
    for(i=0;vis[i];i++) {
        Calc_DrawGlyph(x,vis[i]);
        x+=Calc_GlyphW(vis[i]);
        if((int32_t)cur==start+i+1) { xc=x; }
    }
    if((int32_t)cur==start) { xc=x0First; }
    if((int32_t)cur>=start && !isResult) { OLED_FillRect(xc,10,4,1,OLED_WHITE); }     /* 光标: 插入点右侧下划线 */
}
/* ---- 增量刷新状态 -------------------------------------------------------- */
static uint8_t s_calcValid=0u;
static uint8_t s_calcPrevR=0xFFu,s_calcPrevC=0xFFu,s_calcPrevBlink=0xFFu,s_calcPrevRes=0xFFu;
static uint8_t s_calcPrevCur=0xFFu;
static char    s_calcPrevText[CALC_EXPR_MAX+1];
void Scene_CalcReset(void)
{
    s_calcValid=0u; s_calcPrevR=0xFFu; s_calcPrevC=0xFFu; s_calcPrevBlink=0xFFu;
    s_calcPrevRes=0xFFu; s_calcPrevCur=0xFFu; s_calcPrevText[0]=0;
}
void Scene_Calc(uint32_t tMs,const char *expr,uint8_t cur,uint8_t selR,uint8_t selC,uint8_t isResult)
{
    uint8_t blinkOn=(uint8_t)(((tMs/SC_BLINK_MS)&1u)==0u);
    uint8_t changed=0u;
    uint8_t i;
    if(!s_calcValid) {                                       /* 首帧: 整屏画一次 */
        uint8_t r,c;
        for(r=0u;r<6u;r++) { for(c=0u;c<4u;c++) { if(s_calcKeys[r][c]!=CK_NONE) { Calc_DrawCell(r,c,(uint8_t)(r==selR&&c==selC),blinkOn); } } }
        Calc_DrawDisplay(expr,cur,isResult);
        goto save;
    }
    if(selR!=s_calcPrevR || selC!=s_calcPrevC) {             /* 选中格子移动: 旧框擦掉, 新框亮起 */
        Calc_DrawCell(s_calcPrevR,s_calcPrevC,0u,1u);
        Calc_DrawCell(selR,selC,1u,blinkOn);
    } else if(blinkOn!=s_calcPrevBlink) {                    /* 闪烁相位翻转: 只重画选中那一格 */
        Calc_DrawCell(selR,selC,1u,blinkOn);
    }
    if(isResult!=s_calcPrevRes || cur!=s_calcPrevCur) { changed=1u; }
    for(i=0u;i<=(uint8_t)CALC_EXPR_MAX;i++) {
        if(expr[i]!=s_calcPrevText[i]) { changed=1u; break; }
        if(!expr[i]) { break; }
    }
    if(changed) { Calc_DrawDisplay(expr,cur,isResult); }
save:
    for(i=0u;i<=(uint8_t)CALC_EXPR_MAX;i++) { s_calcPrevText[i]=expr[i]; if(!expr[i]) { break; } }
    s_calcPrevR=selR; s_calcPrevC=selC; s_calcPrevBlink=blinkOn; s_calcPrevRes=isResult;
    s_calcPrevCur=cur;
    s_calcValid=1u;
}

/* ===========================================================================
 * V30 游戏结算界面 (烟花 + 最终得分 + 两个图标)
 * ---------------------------------------------------------------------------
 * 用户上传的两张 jpg 就是这一屏的两个图标：
 *   返回游戏界面 -> 房子；重新开始 -> 环形箭头。
 * 造型用 24x24 的 1-bit 位图（由原图 24px 缩略后阈值化，形状忠实），
 * 外面各套一个 **1px 细线钝角四边形**（G_Box, 圆角 2）。
 * 选中的那个框按 300 ms 相位**闪烁**：相位 0 单线，相位 1 多套一圈 1px。
 * 烟花直接复用闹钟那套 Fw_Spawn/Fw_Step/Fw_Draw。
 * =========================================================================== */
static const uint8_t s_gIcoHome[72]={
    0x00,0x18,0x00,0x00,0x3C,0x00,0x00,0x7E,0x00,0x00,0xFF,0x00,
    0x01,0xFF,0x80,0x03,0xFF,0xC0,0x03,0xFF,0xC0,0x07,0xFF,0xE0,
    0x0F,0xFF,0xF0,0x1F,0xFF,0xF8,0x3F,0xFF,0xFC,0x7F,0xFF,0xFE,
    0x7F,0xFF,0xFF,0xFF,0xFF,0xFF,0xFF,0xFF,0xFF,0x1F,0xFF,0xF8,
    0x0F,0xFF,0xF8,0x0F,0xFF,0xF8,0x0F,0xE7,0xF8,0x0F,0xE7,0xF8,
    0x0F,0xE7,0xF8,0x0F,0xE7,0xF8,0x0F,0xE7,0xF0,0x0F,0xC7,0xF0
};
static const uint8_t s_gIcoRestart[72]={
    0x00,0x10,0x00,0x00,0x70,0x00,0x00,0xF0,0x00,0x03,0xF8,0x00,
    0x07,0xFF,0x80,0x0F,0xFF,0xE0,0x0F,0xFF,0xF0,0x07,0xFF,0xF8,
    0x01,0xFB,0xFC,0x00,0xF8,0xFE,0x30,0x38,0x7E,0x78,0x10,0x3F,
    0xF8,0x00,0x1F,0xF8,0x00,0x1F,0xF8,0x00,0x1F,0xFC,0x00,0x1F,
    0x7C,0x00,0x3F,0x7E,0x00,0x3E,0x7F,0x00,0xFE,0x3F,0xC1,0xFC,
    0x1F,0xFF,0xF8,0x0F,0xFF,0xF0,0x03,0xFF,0xC0,0x00,0xFF,0x00
};
#define GO_BOX_W    28
#define GO_BOX_Y    32
#define GO_BOX_LX   24
#define GO_BOX_RX   76
#define GO_BLINK_MS 300u
static uint8_t  s_goDrawn=0u;
static uint32_t s_goLastT=0u;

/* 24x24 单色位图 (每行 3 字节, MSB 在左) */
/* 进结算时只需把 s_goDrawn 清 0; 真正的初始化(清烟花/重置随机数)在首帧做,
 * 这样少一个导出函数 (省 100 B 代码)。 */
void Scene_GameOverBegin(uint32_t now) { (void)now; s_goDrawn=0u; }
void Scene_GameOver(uint32_t now,uint32_t score,uint8_t sel)
{
    uint16_t i;
    int32_t dt=0;
    uint32_t ph;
    int32_t bx;
    if(s_goDrawn) {
        dt=(int32_t)(now-s_goLastT);
        if(dt<0) { dt=0; } if(dt>100) { dt=100; }
        s_goLastT=now; s_fwClock+=(uint32_t)dt;
    } else {
        for(i=0u;i<FW_ROCKETS;i++) { s_rk[i].alive=0u; }
        for(i=0u;i<FW_SPARKS;i++) { s_sp[i].alive=0u; }
        s_rng=0x2545F491u^now; if(!s_rng) { s_rng=1u; }
        s_goDrawn=1u; s_goLastT=now; s_fwClock=0u; s_nextSpawn=0u; s_side=0u;
    }
    if((int32_t)(s_fwClock-s_nextSpawn)>=0) {
        Fw_Spawn();
        s_nextSpawn=s_fwClock+200u+RndN(340u);
    }
    Fw_Step(dt);
    ph=(now/GO_BLINK_MS)&1u;
    /* 顺序很关键: **先**画得分和图标(它们是"实体", 自带小黑底), **最后**画烟花。
     * 反过来的话, 得分的整条黑板会把上半屏的烟花全部盖掉 (V30 的问题)。
     * 烟花只是 1px 白点, 叠在文字/图形上不会破坏可读性, 但任何位置都看得见。 */
    OLED_Clear();
    /* ---- 最终得分: 底板只做到数字那么大, 不再横贯整屏 ---- */
    {
        int32_t w=G_DigW(5u,3u)+6;              /* 5 位 3 倍宽 + 两边留白 */
        int32_t x0=(128-w)/2;
        OLED_FillRect(x0,1,w,19,OLED_BLACK);
        OLED_DrawRect(x0,1,w,19,OLED_WHITE);
        G_Num(x0+3,4,score,5u,3u);
    }
    /* ---- 两个图标: 框内挖黑, 保证图标干净 ---- */
    for(i=0u;i<2u;i++) {
        bx=(i==0u)?GO_BOX_LX:GO_BOX_RX;
        OLED_FillRect(bx,GO_BOX_Y,GO_BOX_W,GO_BOX_W,OLED_BLACK);
        G_Ico(bx+2,GO_BOX_Y+2,(i==0u)?s_gIcoHome:s_gIcoRestart,24u,24u);
        G_Box(bx,GO_BOX_Y,bx+GO_BOX_W-1,GO_BOX_Y+GO_BOX_W-1,1u);
        if(sel==i && ph) { G_Box(bx-1,GO_BOX_Y-1,bx+GO_BOX_W,GO_BOX_Y+GO_BOX_W,1u); }
    }
    Fw_Draw();                                  /* 烟花最后画 -> 永不遮挡 */
}

